'use strict';
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',campaign:'<path d="m3 10 13-5v14L3 14zM16 9h3a3 3 0 0 1 0 6h-3M5 15l2 6h4l-2-5"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9H3z"/>',brand:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',chevron:'<path d="m9 5 7 7-7 7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',chart:'<path d="M4 4v16h16M8 14l4-5 4 3 5-7"/>',eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7"/><circle cx="12" cy="12" r="3"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3M12 17h.01"/>',pause:'<path d="M8 5v14M16 5v14"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const initial={brand:{name:'내 브랜드',url:'',description:'브랜드 소개를 입력해주세요.',color:'#7355df',tone:'따뜻하고 감성적인'},creatives:[],campaigns:[]};
let state=structuredClone(initial);
let revision=0, connection={configured:false,model:'gpt-4.1-mini'}, saving=Promise.resolve(), saveError=null;
let view=['home','studio','campaigns','library','brand','instagram','performance'].includes(location.hash.slice(1))?location.hash.slice(1):'home';
let current=null, variant=0, generating=false, messages=[], toastTimer, draft=null;
const names={home:'워크스페이스',studio:'AI 스튜디오',campaigns:'캠페인',library:'크리에이티브',brand:'브랜드 키트',instagram:'Instagram',performance:'성과 실험'};
async function api(url, data, method='POST') {
  let response;
  try { response=await fetch(url,{method:data===undefined?'GET':method,headers:data===undefined?{}:{'Content-Type':'application/json'},...(data===undefined?{}:{body:JSON.stringify(data)})}); }
  catch { throw Error('서버 연결이 끊겼습니다. npm start로 서버를 실행해주세요.'); }
  let result;try {result=await response.json()}catch{throw Error('새 Bloom 서버로 접속해주세요: http://localhost:4174')}
  if(!response.ok)throw Error(result.error||'요청을 처리하지 못했습니다.');return result;
}
function persist(){
  const snapshot=structuredClone(state);
  saving=saving.then(async()=>{
    if(saveError)throw saveError;
    const result=await api('/api/state',{state:snapshot,revision},'PUT');revision=result.revision;
  }).catch(error=>{saveError=error;toast('저장 실패: '+error.message);document.querySelector('#save-status')?.replaceChildren('저장 실패 · 작업 백업 필요');});
  return saving;
}
async function saved(){await saving;if(saveError)throw saveError;}
function captureDraft(){capturePerformanceForms();captureBatchDraft();captureEditor();captureVideoDraft();const form=document.querySelector('#create-form');if(form)draft={...draft,...Object.fromEntries(new FormData(form))};}
function captureEditor(){
  const form=document.querySelector('#edit-form');if(!form||!current||generating)return;
  const data=Object.fromEntries(new FormData(form));
  if(data.name?.trim()&&data.headline?.trim()&&Object.keys(data).some(key=>data[key]!==current[key])){
    Object.assign(current,data);saveCreative();
  }
}
function fieldValue(name,fallback=''){return draft?.[name]??current?.[name]??fallback;}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
function go(next){if(generating||directorAttaching||performanceBusy){toast('현재 작업이 끝난 뒤 이동해주세요.');return}captureDraft();view=next;location.hash=next;render();window.scrollTo(0,0);if(next==='performance')loadPerformance();if(next==='instagram')refreshInstagram().then(()=>{if(view==='instagram')render()}).catch(error=>toast(error.message))}
function nav(key,symbol,label){return `<button title="${esc(label)}" class="nav ${view===key?'active':''}" data-view="${key}" ${view===key?'aria-current="page"':''}>${icon(symbol)}${label}${key==='studio'?'<em>AI</em>':''}</button>`}
function wrapText(text,maxWidth,size,maxLines=5){
  const ctx=document.createElement('canvas').getContext('2d');ctx.font=`700 ${size}px sans-serif`;
  const lines=[];
  for(const paragraph of String(text).split('\n')){let line='';for(const character of paragraph){if(ctx.measureText(line+character).width>maxWidth&&line){lines.push(line);line=''}line+=character;}lines.push(line);}
  if(lines.length>maxLines){lines.length=maxLines;lines[maxLines-1]=lines[maxLines-1].slice(0,-1)+'…'}return lines;
}
function creativeImage(item){return item?.image||state.assets?.find(asset=>asset.id===item?.imageRef)?.data||''}
function artwork(item={},type=0){
  const color=item.color||state.brand.color;
  const photo=/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(creativeImage(item))?creativeImage(item):null;
  const center=type===1, x=center?540:80, anchor=center?'middle':'start';
  const headline=wrapText(item.headline||'브랜드의 다음 이야기를\n여기에 담아보세요.',920,76,5);
  const caption=wrapText(item.caption||'',920,30,3);
  const start=type===2?220:660-(headline.length-1)*48;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1080" viewBox="0 0 1080 1080"><rect width="1080" height="1080" fill="${esc(color)}"/>${photo?`<image href="${photo}" width="1080" height="1080" preserveAspectRatio="xMidYMid slice"/><rect width="1080" height="1080" fill="${center?esc(color):'#000000'}" opacity="${center?'.72':'.42'}"/>`:''}<g fill="white" font-family="sans-serif" text-anchor="${anchor}"><text x="${x}" y="120" font-size="32" letter-spacing="4">${esc((item.brand||state.brand.name).slice(0,50))}</text>${headline.map((line,i)=>`<text x="${x}" y="${start+i*94}" font-size="76" font-weight="700">${esc(line)}</text>`).join('')}${caption.map((line,i)=>`<text x="${x}" y="${884+i*42}" font-size="30">${esc(line)}</text>`).join('')}</g></svg>`;
}
function art(item={},type=0,large=false){return `<div class="art workart ${large?'studioart':''}"><img src="data:image/svg+xml;charset=utf-8,${encodeURIComponent(artwork(item,type))}" alt="${esc(item.headline||'광고 미리보기')}"></div>`}
function creativeCard(item,index){return `<button class="creative" data-creative="${esc(item.id||'sample-'+index)}">${art(item,item.variant??index%3)}<div class="creativeinfo"><b>${esc(item.name||['일상의 작은 리추얼','잠깐의 여유, 한 잔의 행복','당신의 오후를 바꾸는 커피'][index%3])}</b><small>${esc(item.channel||'Instagram')} · 저장됨</small></div></button>`}
function home(){return `<div class="heading"><div><div class="eyebrow">YOUR MARKETING, IN BLOOM</div><h1>좋은 아이디어가 자랄 시간이에요.</h1><p class="sub">${esc(state.brand.name)}의 다음 이야기를 함께 만들어볼까요?</p></div><button class="btn" data-view="brand">${icon('brand')}브랜드 관리</button></div><section class="hero"><div class="herocopy"><div class="eyebrow">YOUR AI CMO WORKSPACE</div><h2>광고의 다음 결정,<br>성과에서 시작하세요.</h2><p>대화로 만들고, 서로 다른 가설을 시험하고.<br>실제 성과를 다음 광고 기획에 반영하세요.</p><button class="btn primary" data-view="studio">${icon('spark')}새 광고 만들기</button></div><div class="herovisual" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="floating f1"><img src="assets/coffee.jpg" alt=""><b>Your daily little ritual.</b><small>YOUR NEXT CREATIVE</small></div><div class="floating f2">MAKE SOMETHING<span>worth a pause.</span>Made for your brand.</div><div class="floating f3"><i>✓</i> 새로운 아이디어가 준비됐어요 ${icon('spark')}</div></div></section><div class="sectionhead"><h2>마케팅 한눈에 보기</h2><button class="textbtn" data-view="performance">성과 실험 열기</button></div><div class="stats">${[['저장한 작업',String(state.creatives.length),'크리에이티브','folder'],['캠페인 초안',String(state.campaigns.length),'게시 전 준비','campaign'],['AI 연결',connection.configured?'연결됨':'설정 필요',connection.model,'spark'],['성과 기록',String(state.performance?.observations?.length||0),'직접 입력 · CSV','chart']].map(([label,value,change,symbol])=>`<div class="stat"><div class="statlabel">${label}${icon(symbol)}</div><strong>${value}</strong><small><span class="positive">${change}</span></small></div>`).join('')}</div><div class="gridbottom"><section><div class="sectionhead"><h2>최근 크리에이티브</h2><button class="textbtn" data-view="library">모두 보기</button></div><div class="creativegrid">${state.creatives.length?state.creatives.slice(0,3).map(creativeCard).join(''):'<p class="sub">새 광고 만들기로 첫 작업을 시작하세요.</p>'}</div></section><section><div class="sectionhead"><h2>에이전트 노트</h2><span class="tag">아이디어</span></div><div class="card feed">${[['spark','브랜드의 다음 이야기를 찾아보세요','따뜻한 일상, 새로운 메뉴, 브랜드의 철학. 어떤 이야기든 좋아요.'],['chart','다양한 메시지를 비교해보세요','같은 제품도 다른 헤드라인으로 테스트하면 새로운 반응을 발견할 수 있어요.'],['check','게시 전, 마지막 확인도 잊지 마세요','캠페인을 저장한 뒤 카피와 예산을 검토하세요.']].map(([symbol,title,body])=>`<div class="feeditem"><div class="feedicon">${icon(symbol)}</div><div><b>${title}</b><p>${body}</p></div></div>`).join('')}</div></section></div><div class="footerhint">${icon('help')}원고와 이미지를 직접 편집하고 PNG·SVG로 저장하세요. Instagram 메뉴에서 계정을 연결하고 게시할 수 있습니다.</div>`}
function legacyStudio(){return `<div class="heading"><div><div class="eyebrow">FROM IDEA TO CREATIVE</div><h1>상상을 광고로 만들어보세요.</h1><p class="sub">브랜드의 이야기를 들려주면, 첫 번째 시안을 함께 준비할게요.</p></div></div><div class="studio"><form id="create-form" class="card panel"><div class="previewheader"><h2>무엇을 만들까요?</h2>${icon('spark')}</div><label class="field">브랜드<input name="brand" ${generating?'readonly':''} value="${esc(fieldValue('brand',state.brand.name))}" required maxlength="60"></label><label class="field">광고 아이디어<textarea name="prompt" ${generating?'readonly':''} required maxlength="1000" placeholder="어떤 제품을, 누구에게 알리고 싶으신가요?">${esc(fieldValue('prompt',''))}</textarea></label><div class="chips"><button type="button" class="chip" data-prompt="신제품의 매력을 소개하는 감성적인 광고. 새로운 경험을 선물하세요.">신제품 소개</button><button type="button" class="chip" data-prompt="실제 제공하는 할인 혜택과 기간을 여기에 입력해주세요. 확인된 혜택을 강조하는 프로모션 광고를 작성해줘.">할인 프로모션</button><button type="button" class="chip" data-prompt="우리 브랜드가 일상에 전하는 작은 행복. 편안하고 진솔한 브랜드 스토리를 전해줘.">브랜드 스토리</button></div><div class="row"><label class="field">채널<select name="channel" ${generating?'disabled':''}>${['Instagram','YouTube','Facebook'].map(channel=>`<option ${fieldValue('channel')===channel?'selected':''}>${channel}</option>`).join('')}</select></label><label class="field">포맷<select name="format" ${generating?'disabled':''}>${['이미지 광고','15초 광고 영상'].map(format=>`<option ${(fieldValue('format')===format||(format==='15초 광고 영상'&&fieldValue('format')==='15초 스토리보드'))?'selected':''}>${format}</option>`).join('')}</select></label></div><label class="field">제품 사진<input name="photo" type="file" accept="image/png,image/jpeg,image/webp" ${generating?'disabled':''}><small>PNG · JPG · WebP / 최대 10MB</small></label><button type="button" class="btn wide" id="manual-create" ${generating?'disabled':''}>직접 작성 시작</button><button class="btn primary wide" ${generating?'disabled':''}>${icon('spark')}${generating?'광고 시안을 준비하고 있어요…':'광고 시안 만들기'}</button><div class="notice">${connection.configured?'연결된 AI가 브랜드와 요청을 바탕으로 원고를 작성합니다.':'AI 연결 설정에서 API 키를 연결해주세요. 직접 작성과 파일 저장은 바로 사용할 수 있습니다.'}</div></form><section class="card panel"><div class="previewheader"><h2>크리에이티브 미리보기</h2><div class="row"><button class="btn primary" id="video-open" ${!current?'disabled':''}>광고 영상 만들기</button><button class="btn primary" id="instagram-publish" ${!current||generating||current.channel!=='Instagram'||current.format!=='이미지 광고'?'disabled':''}>Instagram 게시</button><button class="btn" id="export-copy" ${!current?'disabled':''}>원고 저장</button><button class="btn" id="export-png" ${!current?'disabled':''}>PNG 저장</button><button class="btn" id="export" ${!current?'disabled':''}>${icon('download')}SVG 저장</button><button class="btn primary" id="save-campaign" ${!current||generating?'disabled':''}>캠페인 저장</button></div></div><div class="previewcanvas">${art(current||{image:draft?.image||''},variant,true)}</div><div class="scenechips">${['감성적인 순간','브랜드 컬러','강렬한 메시지'].map((text,index)=>`<button data-variant="${index}" class="${variant===index?'selected':''}" aria-pressed="${variant===index}">${text}</button>`).join('')}</div>${current?`<div class="script"><b>${current.format!=='이미지 광고'?'영상 기획 원고':'카피 제안'}</b><br>${esc(current.script)}</div><form id="edit-form" class="editor"><label class="field">작업 이름<input name="name" required maxlength="200" value="${esc(current.name)}"></label><label class="field">헤드라인<textarea name="headline" required maxlength="500">${esc(current.headline)}</textarea></label><label class="field">보조 문구<textarea name="caption" maxlength="500">${esc(current.caption)}</textarea></label><label class="field">${current.format!=='이미지 광고'?'영상 기획 원고':'게시물 본문'}<textarea name="script" maxlength="16000">${esc(current.script)}</textarea></label><button class="btn" ${generating?'disabled':''}>수정 내용 저장</button></form>`:'<p class="sub">왼쪽에서 아이디어를 입력하면 브랜드에 맞춘 시안이 여기에 나타나요.</p>'}<div id="messages">${messages.map(message=>`<div class="message ${message.role==='user'?'user':''}">${esc(message.text)}</div>`).join('')}</div><form id="chat-form" class="chatbar"><input aria-label="수정 요청" name="message" placeholder="예: 헤드라인을 더 짧게 / 할인 강조 / 더 따뜻하게" required maxlength="300" ${!current||generating?'disabled':''}><button class="btn primary" ${!current||generating?'disabled':''}>${generating?'작성 중…':'AI 수정'}</button></form>${current?videoStudio():''}</section></div>`}
function campaigns(){return `<div class="heading"><div><div class="eyebrow">CAMPAIGN DRAFTS</div><h1>캠페인 초안</h1><p class="sub">원고와 일 예산을 정리하고 제작 파일을 준비하세요.</p></div><button class="btn primary" data-view="studio">새 광고 만들기</button></div><div class="card campaigns"><table><thead><tr><th>캠페인 이름</th><th>채널</th><th>일 예산</th><th>관리</th></tr></thead><tbody>${state.campaigns.map(c=>`<tr><td><b>${esc(c.name)}</b><small>게시 전 초안</small></td><td>${esc(c.channel)}</td><td>₩${Number(c.budget).toLocaleString('ko-KR')}</td><td><button class="btn" data-creative="${esc(c.creativeId||'')}">원고 열기</button> <button class="textbtn" data-budget="${esc(c.id)}">예산 수정</button></td></tr>`).join('')||'<tr><td colspan="4">광고 작업에서 캠페인 저장을 누르면 여기에 표시됩니다.</td></tr>'}</tbody></table></div><p class="sub">Instagram 피드 게시는 스튜디오에서 진행하세요. 유료 광고 집행은 포함되지 않습니다.</p>`}
function library(){return `<div class="heading"><div><div class="eyebrow">YOUR CREATIVE COLLECTION</div><h1>크리에이티브 라이브러리</h1><p class="sub">브랜드를 위해 만든 아이디어를 한곳에서 만나보세요.</p></div><button class="btn primary" data-view="studio">${icon('plus')}새 광고 만들기</button></div>${state.creatives.length?`<div class="savedlist"><div class="creativegrid">${state.creatives.map(creativeCard).join('')}</div></div>`:'<div class="card empty">아직 저장한 크리에이티브가 없어요.<br><p class="sub">AI 스튜디오에서 첫 번째 광고 시안을 만들어보세요.</p><button class="btn primary" data-view="studio">첫 광고 만들기</button></div>'}`}
function brand(){return `<div class="heading"><div><div class="eyebrow">CONSISTENTLY, UNIQUELY YOU</div><h1>브랜드 키트</h1><p class="sub">브랜드 이름·소개·색상·톤을 다음 광고 작업에 반영합니다.</p></div></div><div class="brandgrid"><form id="brand-form" class="card panel"><label class="field">브랜드 이름<input name="name" required maxlength="60" value="${esc(state.brand.name)}"></label><label class="field">웹사이트<input name="url" type="url" value="${esc(state.brand.url)}" placeholder="https://yourbrand.com"></label><label class="field">브랜드 소개<textarea name="description" required maxlength="600">${esc(state.brand.description)}</textarea></label><div class="row"><label class="field">대표 색상<input class="colorinput" name="color" type="color" value="${esc(state.brand.color)}"></label><label class="field">브랜드 톤<select name="tone">${['따뜻하고 감성적인','명확하고 전문적인','대담하고 활기찬'].map(tone=>`<option ${state.brand.tone===tone?'selected':''}>${tone}</option>`).join('')}</select></label></div><button class="btn primary wide">브랜드 저장하기</button></form><section class="card panel"><h2 style="margin-bottom:22px">브랜드 프리뷰</h2><div id="brand-preview" class="swatch" style="background:${esc(state.brand.color)}">${esc(state.brand.name)}</div><p class="sub" id="brand-description">${esc(state.brand.description)}</p><div class="notice">브랜드 이름, 색상과 톤을 광고 시안에 반영합니다. 웹사이트 URL은 기록용이며 자동 분석하지 않습니다.</div></section></div>`}
function render(){clearTimeout(instagramTimer);clearTimeout(videoTimer);clearTimeout(batchTimer);document.querySelector('#app').innerHTML=`<div class="shell ${view==='studio'?'studio-mode':''}"><aside class="sidebar"><a href="#home" class="logo" aria-label="Bloom 홈"><span class="flower">✳</span>bloom<span style="color:#a28bdf">.</span></a><button class="workspace" data-view="brand"><span class="avatar">${esc(state.brand.name[0]||'B')}</span><span>${esc(state.brand.name)}<small>내 워크스페이스</small></span></button><div class="navlabel">WORKSPACE</div>${nav('home','home','홈')}${nav('studio','spark','AI 스튜디오')}${nav('campaigns','campaign','캠페인')}${nav('performance','chart','성과 실험')}${nav('library','folder','크리에이티브')}${nav('brand','brand','브랜드 키트')}${nav('instagram','campaign','Instagram')}<div class="bottom"><div class="trial">아이디어를 실제 작업으로.<p>브랜드의 다음 챕터를<br>Bloom과 함께 만들어보세요.</p><div class="meter"><span></span></div><small>BLOOM AI CMO · v0.6</small></div><button class="nav" id="help">${icon('help')}사용 안내</button><div class="profile"><span class="avatar" style="background:#34313e;color:#c9b8eb">T</span><span>내 작업 공간<small>Personal workspace</small></span></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="mobilemenu iconbutton" id="menu" aria-label="메뉴 열기">${icon('menu')}</button><span>워크스페이스</span>${icon('chevron')}<b>${names[view]}</b></div><div class="topactions"><span class="demo" id="save-status" role="status">${saveError?'저장 실패 · 작업 백업 필요':'서버 저장'}</span><button class="btn" id="settings">${connection.configured?'AI 연결됨':'AI 연결 설정'}</button><button class="textbtn" id="backup">작업 백업</button><button class="iconbutton" id="notifications" aria-label="알림">${icon('bell')}</button><span class="avatar" style="border-radius:50%;width:30px;height:30px;font-size:12px;background:#eee9f8;color:#8970ae">T</span></div></header><div class="content">${({home,studio,campaigns,library,brand,instagram:instagramView,performance:performanceView})[view]()}</div></main></div>`;bind()}
function download(filename,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function saveCreative(){state.creatives=state.creatives.filter(item=>item.id!==current.id);state.creatives.unshift(structuredClone(current));return persist()}
function modal(content){const dialog=document.querySelector('#modal');dialog.innerHTML=content;dialog.showModal();dialog.querySelector('[data-close]')?.addEventListener('click',()=>dialog.close())}
function campaignModal(existing){modal(`<h2>${existing?'일 예산 수정':'캠페인으로 저장'}</h2><form id="campaign-form">${!existing?`<label class="field">캠페인 이름<input name="name" required maxlength="200" value="${esc(current.name)}"></label>`:''}<label class="field">일 예산 (원)<input name="budget" type="number" min="1000" max="10000000" step="1000" required value="${existing?.budget||30000}"></label><div class="notice">검토 대기 상태로 저장됩니다. 실제 광고가 게시되거나 결제되지 않습니다.</div><div class="row"><button type="button" class="btn" data-close>취소</button><button class="btn primary">저장</button></div></form>`);document.querySelector('#campaign-form').onsubmit=async event=>{event.preventDefault();const data=new FormData(event.target);if(existing){existing.budget=Number(data.get('budget'))}else{state.campaigns.unshift({id:crypto.randomUUID(),name:data.get('name').trim(),channel:current.channel,budget:Number(data.get('budget')),status:'paused',creativeId:current.id})}await persist();try{await saved();document.querySelector('#modal').close();toast('캠페인 초안을 저장했습니다.');go('campaigns')}catch(error){toast(error.message)}}}
function bind(){bindPerformance();bindInstagram();bindVideos();bindDirector();bindEditor();bindCreationModes();document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>go(button.dataset.view));document.querySelector('#menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');document.querySelector('#settings').onclick=settingsModal;
document.querySelector('#backup').onclick=()=>{captureEditor();download('bloom-workspace.json',JSON.stringify(state,null,2),'application/json')};
document.querySelector('#help').onclick=()=>modal('<h2>Bloom 사용 안내</h2><p class="sub">브랜드 키트를 설정한 다음 광고 아이디어와 제품 사진을 입력하세요. AI 연결 후 원고 생성·수정을 사용할 수 있습니다. 직접 작성은 연결 없이 가능합니다.</p><p class="sub">작업 내용은 이 컴퓨터의 서버 파일에 저장됩니다. PNG와 SVG는 광고 이미지, 작업 백업은 전체 원본 데이터입니다. 영상 편집에서 장면 문구와 비율을 정해 15초 MP4로 만들 수 있습니다. Instagram 메뉴에서 계정을 연결하면 이미지 피드에 게시할 수 있습니다. 완성 영상은 재생하고 MP4로 저장할 수 있습니다.</p><button class="btn primary wide" data-close>확인</button>');document.querySelector('#notifications').onclick=()=>toast('새 알림이 없습니다. 저장된 캠페인은 캠페인 메뉴에서 확인하세요.');
document.querySelectorAll('[data-creative]').forEach(button=>button.onclick=()=>{captureDraft();if(generating||directorAttaching)return;current=structuredClone(state.creatives.find(item=>item.id===button.dataset.creative)||null);draft=null;messages=[];studioMode='chat';editorTime=0;editorScene=0;editorTab='scenes';variant=current?.variant??0;view='studio';location.hash='studio';render()});
document.querySelectorAll('[data-prompt]').forEach(button=>button.onclick=()=>{document.querySelector('[name=prompt]').value=button.dataset.prompt;captureDraft()});
document.querySelectorAll('[data-variant]').forEach(button=>button.onclick=()=>{if(generating)return;captureDraft();variant=Number(button.dataset.variant);if(current){current.variant=variant;saveCreative()}render()});
const form=document.querySelector('#create-form');
if(form){
  form.oninput=captureDraft;
  form.querySelector('[name=photo]').onchange=async event=>{
    const file=event.target.files[0];if(!file)return;
    try{
      if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('10MB 이하의 PNG, JPG, WebP 사진을 선택해주세요.');
      const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('사진을 읽지 못했습니다.'));reader.readAsDataURL(file)});
      const image=await loadImage(source);const scale=Math.min(1,1600/Math.max(image.width,image.height));
      const canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);
      canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);
      captureDraft();draft.image=canvas.toDataURL('image/jpeg',.88);
      if(current){current.image=draft.image;current.imageVersion=crypto.randomUUID();await saveCreative();await saved();}
      render();toast('제품 사진을 반영했습니다.');
    }catch(error){toast(error.message)}
  };
  document.querySelector('#manual-create').onclick=async()=>{
    captureDraft();const data={...draft};
    if(!data.brand?.trim()){toast('브랜드 이름을 입력해주세요.');return}
    current={id:crypto.randomUUID(),brand:data.brand.trim(),prompt:data.prompt||'',channel:data.channel,format:data.format,name:data.brand+' 광고',headline:'헤드라인을 입력해주세요.',caption:'',script:'',image:data.image||creativeImage(current),color:state.brand.color,variant:0};
    variant=0;draft=null;messages=[];await saveCreative();render();try{await saved();toast('직접 편집할 작업을 만들었습니다.')}catch(error){toast(error.message)}
  };
  form.onsubmit=async event=>{
    event.preventDefault();captureDraft();const data={...draft};
    if(!data.prompt?.trim()||!data.brand?.trim()){toast('브랜드와 광고 아이디어를 입력해주세요.');return}
    if(!connection.configured){settingsModal();return}
    const photo=data.image||creativeImage(current);generating=true;render();
    try{
      const result=await api('/api/creative',{brand:{...state.brand,name:data.brand},prompt:data.prompt,channel:data.channel,format:data.format});
      current={...result,id:crypto.randomUUID(),brand:data.brand,prompt:data.prompt,channel:data.channel,format:data.format,image:photo,color:state.brand.color,variant:0};
      variant=0;draft=null;messages=[{role:'assistant',text:'광고 원고를 작성했습니다. 문구를 직접 편집하거나 AI에 수정을 요청하세요.'}];
      await saveCreative();await saved();toast('새 광고를 저장했습니다.');
    }catch(error){toast(error.message)}finally{generating=false;render()}
  };
}
const edit=document.querySelector('#edit-form');if(edit){edit.oninput=()=>{const data=Object.fromEntries(new FormData(edit));document.querySelector('.previewcanvas').innerHTML=art({...current,...data},variant,true)};edit.onchange=captureEditor;}if(edit)edit.onsubmit=async event=>{
  event.preventDefault();const data=Object.fromEntries(new FormData(edit));
  if(!data.headline.trim()||!data.name.trim()){toast('작업 이름과 헤드라인을 입력해주세요.');return}
  captureDraft();Object.assign(current,data);await saveCreative();render();try{await saved();toast('수정 내용을 저장했습니다.')}catch(error){toast(error.message)}
};
const chat=document.querySelector('#chat-form');if(chat)chat.onsubmit=async event=>{
  event.preventDefault();const text=new FormData(chat).get('message').trim();if(!text||!current||generating)return;
  if(!connection.configured){settingsModal();return}
  captureDraft();const existing=structuredClone(current);generating=true;render();
  try{
    const result=await api('/api/creative',{brand:{...state.brand,name:existing.brand},prompt:existing.prompt||'현재 광고를 수정합니다.',channel:existing.channel,format:existing.format,existing:{name:existing.name,headline:existing.headline,caption:existing.caption,script:existing.script},message:text});
    Object.assign(current,result);messages.push({role:'user',text},{role:'assistant',text:'수정 요청을 반영했습니다.'});
    await saveCreative();await saved();toast('AI 수정 내용을 저장했습니다.');
  }catch(error){toast(error.message)}finally{generating=false;render()}
};
const copy=document.querySelector('#export-copy');if(copy)copy.onclick=()=>{captureEditor();if(current)download('bloom-copy.txt',[current.name,current.headline,current.caption,current.script].join('\n\n'),'text/plain;charset=utf-8')};
const exportButton=document.querySelector('#export');if(exportButton)exportButton.onclick=()=>{captureEditor();if(current)download('bloom-creative.svg',artwork(current,variant),'image/svg+xml')};
const png=document.querySelector('#export-png');if(png)png.onclick=async()=>{
  captureEditor();if(!current)return;
  try{await document.fonts.ready;const img=await loadImage('data:image/svg+xml;charset=utf-8,'+encodeURIComponent(artwork(current,variant)));
    const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1080;canvas.getContext('2d').drawImage(img,0,0);
    const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG 생성에 실패했습니다.');
    download('bloom-creative.png',blob,'image/png');toast('1080×1080 PNG를 저장했습니다.');
  }catch(error){toast(error.message)}
};
const save=document.querySelector('#save-campaign');if(save)save.onclick=()=>{captureEditor();campaignModal()};document.querySelectorAll('[data-budget]').forEach(button=>button.onclick=()=>campaignModal(state.campaigns.find(item=>item.id===button.dataset.budget)));
const brandForm=document.querySelector('#brand-form');if(brandForm){brandForm.oninput=()=>{const data=new FormData(brandForm);document.querySelector('#brand-preview').style.background=data.get('color');document.querySelector('#brand-preview').textContent=data.get('name');document.querySelector('#brand-description').textContent=data.get('description')};brandForm.onsubmit=async event=>{event.preventDefault();const data=new FormData(brandForm);if(!data.get('name').trim()||!data.get('description').trim()){toast('브랜드 이름과 소개를 입력해주세요.');return}state.brand=Object.fromEntries(data);state.brand.name=state.brand.name.trim();await persist();render();try{await saved();toast('브랜드 키트를 저장했습니다.')}catch(error){toast(error.message)}}}}
function loadImage(source){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('이미지를 읽지 못했습니다.'));image.src=source})}
function settingsModal(){
  modal(`<h2>AI 연결 설정</h2><p class="sub">OpenAI API 키로 연결합니다. 원고 생성·수정 시 브랜드 정보와 요청 문구가 OpenAI로 전송되며, 연결한 API 프로젝트에 사용료가 청구됩니다. 대화형 제작에서는 제품 사진도 AI에 전송해 내용을 참고합니다.</p><form id="settings-form"><label class="field">API 키<input name="apiKey" type="password" autocomplete="off" placeholder="${connection.configured?'연결된 키 유지 (변경할 때만 입력)':'sk-…'}" ${connection.configured?'':'required'}></label><label class="field">모델<input name="model" required value="${esc(connection.model)}"></label><p class="sub">키는 서버 메모리에만 유지합니다. 서버 재시작 후 다시 연결하거나 OPENAI_API_KEY 환경 변수를 사용하세요.</p><p id="connection-error" role="alert"></p><div class="row"><button class="btn" type="button" data-close>닫기</button><button class="btn primary">연결 확인</button></div></form>`);
  const form=document.querySelector('#settings-form');form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('.primary');button.disabled=true;button.textContent='연결 확인 중…';try{connection=await api('/api/settings',Object.fromEntries(new FormData(form)));document.querySelector('#modal').close();captureDraft();render();toast('AI 연결을 확인했습니다.')}catch(error){document.querySelector('#connection-error').textContent=error.message}finally{button.disabled=false;button.textContent='연결 확인'}};
}
const instagramLabels={queued:'게시 준비 중',uploading:'이미지 업로드 중',processing:'Instagram 이미지 처리 중',publishing:'게시 중',published:'게시 완료',failed:'게시 실패',uncertain:'게시 여부 확인 필요'};
let instagramConnection={connected:false,account:null,loginAvailable:false,serviceReady:false}, instagramPosts=[], instagramTimer;
const instagramNotices={connected:'Instagram 계정을 연결했습니다. 광고를 준비하고 게시해보세요.',cancelled:'Instagram 연결을 취소했습니다. 원할 때 다시 연결할 수 있습니다.',invalid:'연결 요청을 확인하지 못했습니다. 비즈니스·크리에이터 계정으로 다시 연결해주세요.',permissions:'계정 확인과 게시 권한을 모두 허용해주세요.',failed:'Instagram 연결을 완료하지 못했습니다. 잠시 후 다시 시도해주세요.',unavailable:'Instagram 연결 서비스를 준비 중입니다. 잠시 후 다시 시도해주세요.'};
let instagramNotice='';
function instagramView(){
  const connected=instagramConnection.connected;
  const account=instagramConnection.account;
  return `<div class="heading"><div><div class="eyebrow">INSTAGRAM PUBLISHING</div><h1>Instagram</h1><p class="sub">계정을 연결하고 완성한 광고를 피드에 게시하세요.</p></div><button class="btn" id="instagram-refresh">상태 새로고침</button></div>${instagramNotice?`<p class="notice" role="status">${esc(instagramNotice)}</p>`:''}<div class="brandgrid"><section class="card panel instagram-account"><div class="instagram-symbol">◎</div><h2>${connected?'@'+esc(account.username):instagramConnection.reconnectRequired?'Instagram에 다시 연결해주세요':'Instagram과 연결하세요'}</h2><p class="sub">${connected?'게시할 계정이 연결되어 있습니다. 이미지와 캡션을 확인한 뒤 게시할 수 있습니다.':'Instagram에서 로그인하고 계정 확인과 게시 권한을 허용하면 연결됩니다.'}</p><button class="btn primary" id="instagram-login" ${!instagramConnection.loginAvailable?'disabled':''}>${connected?'다른 계정 연결':'Instagram으로 '+(instagramConnection.reconnectRequired?'다시 연결':'로그인')}</button>${connected?'<button class="btn" id="instagram-disconnect">연결 해제</button>':''}${!instagramConnection.serviceReady?'<p class="sub" role="status">Instagram 연결 서비스를 준비 중입니다. 준비가 끝나면 이 버튼으로 연결할 수 있습니다.</p>':''}<p class="sub">비즈니스 또는 크리에이터 계정으로 연결할 수 있습니다.</p></section><section class="card panel"><h2>광고에서 게시까지</h2><ol class="setupsteps"><li><b>계정 연결</b><br>Instagram에서 로그인하고 권한을 허용하세요.</li><li><b>광고 준비</b><br>스튜디오에서 사진과 문구를 완성하세요.</li><li><b>확인 후 게시</b><br>Instagram 게시를 누르고 대상 계정·이미지·캡션을 확인하세요.</li></ol><button class="btn" data-view="studio">광고 만들기</button></section></div><div class="sectionhead"><h2>게시 기록</h2></div><div id="instagram-posts">${instagramPostList()}</div>`;
}
function instagramPostList(){return instagramPosts.length?instagramPosts.map(job=>`<article class="card panel postrecord"><div><b>${esc(job.name)}</b><p class="sub">@${esc(job.account.username)} · ${esc(new Date(job.createdAt).toLocaleString('ko-KR'))}</p><p class="poststatus" role="status">${instagramLabels[job.status]||esc(job.status)}</p>${job.error?`<p class="posterror">${esc(job.error)}</p>`:''}${job.mediaId?`<p class="sub">게시물 ID: ${esc(job.mediaId)}</p>`:''}${job.permalink?`<a class="btn" href="${esc(job.permalink)}" target="_blank" rel="noopener noreferrer">게시물 열기</a>`:''}${job.status==='uncertain'?`<button class="btn" data-instagram-check="${esc(job.id)}">게시 상태 확인</button>`:''}</div><p class="postcaption">${esc(job.caption)}</p></article>`).join(''):'<div class="card empty">아직 게시한 기록이 없습니다.</div>'}
async function refreshInstagram(){
  const [status,posts]=await Promise.all([api('/api/instagram/status'),api('/api/instagram/posts')]);
  instagramConnection=status;instagramPosts=posts;
}
function pollInstagram(){
  clearTimeout(instagramTimer);
  if(view!=='instagram'||!instagramPosts.some(job=>['queued','uploading','processing','publishing'].includes(job.status)))return;
  instagramTimer=setTimeout(async()=>{try{await refreshInstagram();if(view==='instagram'){document.querySelector('#instagram-posts').innerHTML=instagramPostList();bindInstagramChecks();pollInstagram()}}catch(error){toast(error.message)}},3000);
}
function bindInstagramChecks(){document.querySelectorAll('[data-instagram-check]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(`/api/instagram/posts/${button.dataset.instagramCheck}/check`,{});await refreshInstagram();render()}catch(error){toast(error.message);button.disabled=false}})}
function bindInstagram(){
  const refresh=document.querySelector('#instagram-refresh');if(refresh)refresh.onclick=async()=>{try{await refreshInstagram();render()}catch(error){toast(error.message)}};
  const login=document.querySelector('#instagram-login');if(login)login.onclick=async()=>{captureDraft();login.disabled=true;try{await saved();try{sessionStorage.setItem('bloom.oauth-return',JSON.stringify({creativeId:current?.id,draft:draft?{brand:draft.brand,prompt:draft.prompt,channel:draft.channel,format:draft.format}:null}))}catch{}const result=await api('/api/instagram/login',{});location.assign(result.url)}catch(error){toast(error.message);login.disabled=false}};
  const disconnect=document.querySelector('#instagram-disconnect');if(disconnect)disconnect.onclick=async()=>{try{instagramConnection=await api('/api/instagram/disconnect',{});render();toast('연결을 해제했습니다. 이미 접수한 게시 요청은 계속 처리됩니다.')}catch(error){toast(error.message)}};
  const publish=document.querySelector('#instagram-publish');if(publish)publish.onclick=instagramPublishModal;
  bindInstagramChecks();pollInstagram();
}
async function instagramPublishModal(){
  captureEditor();if(!current||generating)return;
  const creative=structuredClone(current);
  if(creative.channel!=='Instagram'||creative.format!=='이미지 광고'){toast('Instagram 이미지 광고 작업을 선택해주세요.');return}
  const button=document.querySelector('#instagram-publish');button.disabled=true;
  try{
    await saved();await refreshInstagram();
    if(!instagramConnection.connected||!instagramConnection.serviceReady){go('instagram');toast('Instagram 계정을 먼저 연결해주세요.');return}
    await document.fonts.ready;
    const image=await loadImage('data:image/svg+xml;charset=utf-8,'+encodeURIComponent(artwork(creative,creative.variant)));
    const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1080;canvas.getContext('2d').drawImage(image,0,0);
    const jpeg=canvas.toDataURL('image/jpeg',.92);
    const account=structuredClone(instagramConnection.account), requestId=crypto.randomUUID();
    modal(`<h2>Instagram에 게시</h2><p class="sub">게시 계정: <b>@${esc(account.username)}</b> · 피드 이미지 1장</p><img class="publishpreview" src="${jpeg}" alt="게시할 완성 이미지"><form id="instagram-publish-form"><label class="field">캡션<textarea name="caption" maxlength="2200" rows="6">${esc(creative.script||[creative.headline,creative.caption].filter(Boolean).join('\n\n'))}</textarea></label><p class="sub">게시를 누르면 완성 이미지가 게시용 공개 주소에 업로드되고 이미지와 캡션이 위 Instagram 계정의 피드에 게시됩니다.</p><p id="instagram-publish-error" role="alert"></p><div class="row"><button type="button" class="btn" data-close>취소</button><button class="btn primary">@${esc(account.username)}에 지금 게시</button></div></form>`);
    document.querySelector('#instagram-publish-form').onsubmit=async event=>{
      event.preventDefault();const form=event.target, submit=form.querySelector('.primary');submit.disabled=true;submit.textContent='게시 요청 중…';
      try{
        const job=await api('/api/instagram/posts',{requestId,creativeId:creative.id,accountId:account.id,image:jpeg,caption:new FormData(form).get('caption')});
        document.querySelector('#modal').close();await refreshInstagram();go('instagram');toast(job.status==='published'?'이미 게시한 이미지입니다. 게시 기록을 확인해주세요.':'게시 요청을 접수했습니다. 아래에서 진행 상태를 확인하세요.');
      }catch(error){document.querySelector('#instagram-publish-error').textContent=error.message;submit.disabled=false;submit.textContent='게시 요청 다시 확인'}
    };
  }catch(error){toast(error.message)}finally{if(button.isConnected)button.disabled=false}
}

let videoJobs=[],videoCapabilities={available:false},videoTimer;
const videoAudio=new Map();
function defaultVideoPlan(){return current?.videoDraft||{aspect:'9:16',scenes:[{title:(current?.headline||'제품의 이야기를 시작하세요').slice(0,42),body:(current?.caption||'').slice(0,60)},{title:(current?.caption||current?.brand||'제품의 매력').slice(0,42),body:''},{title:(current?.brand||'브랜드').slice(0,42),body:'자세히 알아보기'}]}}
function videoStudio(){
  const plan=defaultVideoPlan();
  return `<section class="video-studio" id="video-studio"><div class="sectionhead"><div><div class="eyebrow">VIDEO AD</div><h2>광고 영상 제작</h2></div><button class="btn" id="video-ai-plan" ${generating?'disabled':''}>AI로 장면 기획</button></div><p class="sub">제품 사진에 줌·이동 효과와 장면별 자막을 넣어 ${plan.duration||15}초 MP4로 만듭니다.</p><form id="video-form"><label class="field">영상 비율<select name="aspect"><option value="9:16" ${plan.aspect==='9:16'?'selected':''}>세로형 9:16 · 720×1280</option><option value="1:1" ${plan.aspect==='1:1'?'selected':''}>정사각형 1:1 · 720×720</option></select></label><div class="video-scenes">${plan.scenes.map((scene,index)=>`<div class="video-scene"><b>장면 ${index+1} · ${(index*(plan.duration||15)/3).toFixed(1)}–${((index+1)*(plan.duration||15)/3).toFixed(1)}초</b><label class="field">제목<textarea name="title${index}" required maxlength="42" ${generating?'readonly':''}>${esc(scene.title)}</textarea></label><label class="field">보조 문구<textarea name="body${index}" maxlength="60" ${generating?'readonly':''}>${esc(scene.body)}</textarea></label></div>`).join('')}</div><label class="field">음성 또는 음악 파일 (선택)<input name="audio" type="file" accept="audio/mpeg,audio/wav,audio/x-wav,audio/mp4,audio/aac,audio/ogg,audio/webm"><small>${videoAudio.has(current.id)?esc(videoAudio.get(current.id).name)+' 선택됨':'최대 5MB · 없으면 무음 영상으로 제작합니다.'}</small></label><p class="sub">직접 사용할 권한이 있는 오디오를 선택하세요. 오디오는 영상 길이에 맞춰 조정됩니다.</p>${!creativeImage(current)?'<p class="notice">왼쪽에서 제품 사진을 업로드하면 영상을 제작할 수 있습니다.</p>':''}${!videoCapabilities.available?'<p class="notice">영상 렌더러를 준비하지 못했습니다. 서버에서 npm ci로 의존성을 설치해주세요.</p>':''}<button class="btn primary wide" ${!creativeImage(current)||!videoCapabilities.available||generating?'disabled':''}>MP4 만들기</button><p id="video-error" class="posterror" role="alert"></p></form><div id="video-results">${videoResultList()}</div></section>`;
}
function videoResultList(){
  const items=videoJobs.filter(job=>job.creativeId===current?.id);
  return items.map(job=>`<article class="video-result card panel"><div class="previewheader"><h2>${job.status==='ready'?'완성된 광고 영상':job.status==='failed'?'영상 제작 실패':job.status==='queued'?'영상 제작 대기':'영상 렌더링 중'}</h2><span class="sub">${job.width}×${job.height} · ${job.duration||15}초 · ${job.hasAudio?'오디오 포함':'무음'}</span></div>${job.status==='ready'?`<video controls playsinline preload="metadata" poster="${esc(job.posterUrl)}" src="${esc(job.fileUrl)}"></video><a class="btn primary" href="${esc(job.fileUrl)}?download=1" download="bloom-ad.mp4">MP4 다운로드</a>`:job.status==='failed'?`<p class="posterror">${esc(job.error)}</p>`:`<progress max="100" value="${job.progress||0}"></progress><p class="sub" role="status">${job.status==='queued'?'앞선 작업이 끝나면 시작합니다.':String(job.progress||0)+'% · 화면을 이동해도 서버에서 계속 제작합니다.'}</p>`}</article>`).join('');
}
function captureVideoDraft(){
  const form=document.querySelector('#video-form');if(!form||!current||generating)return;
  const data=new FormData(form);const next={...current.videoDraft,aspect:data.get('aspect'),scenes:Array.from({length:3},(_,i)=>({title:data.get('title'+i)||'',body:data.get('body'+i)||''}))};
  if(next.scenes.some(scene=>!scene.title.trim()))return;
  if(JSON.stringify(next)!==JSON.stringify(current.videoDraft)){current.videoDraft=next;saveCreative()}
}
async function refreshVideos(){const [status,jobs]=await Promise.all([api('/api/videos/status'),api('/api/videos')]);videoCapabilities=status;videoJobs=jobs}
function pollVideos(){
  clearTimeout(videoTimer);if(view!=='studio'||!videoJobs.some(job=>job.creativeId===current?.id&&['queued','rendering'].includes(job.status)))return;
  videoTimer=setTimeout(async()=>{try{await refreshVideos();const target=document.querySelector('#video-results');if(target)target.innerHTML=videoResultList();updateDirectorPreview();pollVideos()}catch(error){toast(error.message)}},1500);
}
function bindVideos(){
  const open=document.querySelector('#video-open');if(open)open.onclick=()=>document.querySelector('#video-studio')?.scrollIntoView({behavior:'smooth'});
  const form=document.querySelector('#video-form');if(!form)return;
  form.onchange=captureVideoDraft;
  form.querySelector('[name=audio]').onchange=event=>{const file=event.target.files[0];if(!file){videoAudio.delete(current.id);return}if(file.size>5*1024*1024){toast('5MB 이하의 오디오를 선택해주세요.');event.target.value='';return}videoAudio.set(current.id,file);directorAudioChanges.add(current.id);event.target.closest('label').querySelector('small').textContent=file.name+' 선택됨'};
  document.querySelector('#video-ai-plan').onclick=async()=>{
    captureDraft();if(!connection.configured){settingsModal();return}const id=current.id,aspect=defaultVideoPlan().aspect;
    generating=true;render();try{await saved();const plan=await api('/api/video-plan',{creativeId:id,aspect});current.videoDraft=plan;await saveCreative();await saved();toast('3개 장면을 기획했습니다. 문구를 확인하고 영상을 만들어보세요.')}catch(error){toast(error.message)}finally{generating=false;render();document.querySelector('#video-studio')?.scrollIntoView({behavior:'smooth'})}
  };
  form.onsubmit=async event=>{
    event.preventDefault();captureDraft();const id=current.id,plan=structuredClone(current.videoDraft);const button=form.querySelector('button');button.disabled=true;button.textContent='제작 요청 중…';
    try{await saved();const file=videoAudio.get(id);let audio;
      if(file)audio=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('오디오 파일을 읽지 못했습니다.'));reader.readAsDataURL(file)});
      const created=await api('/api/videos',{creativeId:id,plan,audio});if(current?.id===id){current.latestVideoJobId=created.id;await saveCreative()}await refreshVideos();const results=document.querySelector('#video-results');if(results)results.innerHTML=videoResultList();pollVideos();const error=document.querySelector('#video-error');if(error)error.textContent='';toast('영상 제작을 접수했습니다. 완성되면 아래에서 재생하고 저장할 수 있습니다.');
    }catch(error){const target=document.querySelector('#video-error');if(target)target.textContent=error.message;else toast(error.message)}finally{button.disabled=false;button.textContent='MP4 만들기'}
  };
  pollVideos();
}

let directorAttaching=false,pendingDirector='',directorError='',renderingDirector=false;
const directorDrafts=new Map(),directorAudioChanges=new Set();
const looks={warm:'따뜻하게',bold:'강렬하게',minimal:'간결하게'},motions={gentle:'부드러운 움직임',dynamic:'역동적인 움직임',still:'정적인 구성'};
function readyForDirector(){return !!current&&(current.directorReady??!!current.videoDraft)}
function ensureDirectorProject(){
  if(current)return current;
  current={id:crypto.randomUUID(),brand:state.brand.name,name:state.brand.name+' 광고 영상',prompt:'',headline:'광고를 함께 기획해요',caption:'',script:'',channel:'Instagram',format:'15초 광고 영상',variant:0,color:state.brand.color,image:'',conversation:[],directorReady:false,directorBrief:{product:'',audience:'',tone:'',goal:''}};
  if(directorDrafts.has('new')){directorDrafts.set(current.id,directorDrafts.get('new'));directorDrafts.delete('new')}
  return current;
}
function normalizedDirectorPlan(plan){return{aspect:plan.aspect,duration:plan.duration||15,style:plan.style||'warm',motion:plan.motion||'gentle',scenes:plan.scenes}}
function updateDirectorPreview(){const target=document.querySelector('#director-preview');if(target){target.innerHTML=directorPreview();const button=document.querySelector('#director-render');if(button)button.onclick=()=>renderDirectorVideo();bindEditorPlayback();updateEditorChrome()}}
async function readProductPhoto(file){
  if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('10MB 이하의 PNG, JPG, WebP 사진을 선택해주세요.');
  const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('사진을 읽지 못했습니다.'));reader.readAsDataURL(file)});
  const image=await loadImage(source),scale=Math.min(1,1600/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.88);
}
function recordDirectorExecution(project,result){
  const event={tool:'render_video',jobId:result.id,status:result.status,duration:result.duration,at:new Date().toISOString()};
  project.executions=[...(project.executions||[]),event].slice(-30);
}
async function renderDirectorVideo(){
  if(renderingDirector||!current||!readyForDirector())return;
  captureDraft();const project=current,plan=structuredClone(project.videoDraft),file=videoAudio.get(project.id);
  renderingDirector=true;directorError='';updateDirectorPreview();
  try{await saved();let audio;if(file)audio=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('오디오를 읽지 못했습니다.'));reader.readAsDataURL(file)});
    const result=await api('/api/videos',{creativeId:project.id,plan,audio});recordDirectorExecution(project,result);project.latestVideoJobId=result.id;directorAudioChanges.delete(project.id);if(current?.id===project.id){await saveCreative();await saved()}await refreshVideos();updateDirectorPreview();pollVideos();
  }catch(error){directorError='영상 제작 도구: '+error.message;if(current?.id===project.id){project.executions=[...(project.executions||[]),{tool:'render_video',status:'failed',error:error.message,at:new Date().toISOString()}].slice(-30);await saveCreative();}toast(directorError)}finally{renderingDirector=false;if(view==='studio'){render();pollVideos()}}
}
function bindDirector(){
  const form=document.querySelector('#director-form');if(!form)return;
  const input=document.querySelector('#director-message');input.oninput=()=>directorDrafts.set(current?.id||'new',input.value);
  document.querySelectorAll('[data-director-suggestion]').forEach(button=>button.onclick=()=>{input.value=button.dataset.directorSuggestion;directorDrafts.set(current?.id||'new',input.value);input.focus()});
  document.querySelector('#director-new').onclick=()=>{if(generating||directorAttaching)return;captureDraft();current=null;draft=null;messages=[];directorError='';directorDrafts.delete('new');editorTime=0;editorScene=0;editorTab='scenes';render()};
  const photo=document.querySelector('#director-photo');photo.onchange=async event=>{
    const file=event.target.files[0];if(!file)return;captureDraft();const project=ensureDirectorProject();directorAttaching=true;directorError='';render();
    try{project.image=await readProductPhoto(file);project.imageVersion=crypto.randomUUID();await saveCreative();await saved()}catch(error){directorError=error.message}finally{directorAttaching=false;render()}
  };
  const audio=document.querySelector('#director-audio');audio.onchange=async event=>{const file=event.target.files[0];if(!file)return;if(file.size>5*1024*1024){directorError='5MB 이하 오디오를 선택해주세요.';render();return}const project=ensureDirectorProject();videoAudio.set(project.id,file);directorAudioChanges.add(project.id);await saveCreative();render()};
  const mute=document.querySelector('#director-mute');if(mute)mute.onclick=()=>{videoAudio.delete(current.id);directorAudioChanges.add(current.id);render()};
  form.onsubmit=async event=>{
    event.preventDefault();const text=new FormData(form).get('message')?.trim();if(!text||generating||directorAttaching)return;
    directorDrafts.set(current?.id||'new',text);if(!connection.configured){settingsModal();return}
    captureDraft();const project=ensureDirectorProject();if(!project.prompt)project.prompt=text.slice(0,1000);
    await saveCreative();generating=true;pendingDirector=text;directorError='';render();let shouldRender=false;
    try{
      await saved();const result=await api('/api/director',{creativeId:project.id,message:text,audioAvailable:videoAudio.has(project.id)});
      const fields=['brand','name','headline','caption','script','channel'];for(const key of fields)project[key]=result.creative[key];
      if(project.videoDraft)rememberEditorPlan(project.videoDraft);project.format='15초 광고 영상';project.videoDraft=result.plan;editorTime=Math.min(editorTime,result.plan.duration);project.directorBrief=result.brief;project.directorReady=result.ready;
      if(result.audio==='mute'){videoAudio.delete(project.id);directorAudioChanges.add(project.id);}
      project.conversation=[...(project.conversation||[]),{role:'user',text},{role:'assistant',text:result.reply}].slice(-100);
      project.executions=[...(project.executions||[]),{tool:'update_plan',status:'completed',at:new Date().toISOString()}].slice(-30);
      draft=null;await saveCreative();await saved();directorDrafts.delete(project.id);shouldRender=result.action==='render';
    }catch(error){directorError=error.message}finally{generating=false;pendingDirector='';render();const transcript=document.querySelector('#director-transcript');if(transcript)transcript.scrollTop=transcript.scrollHeight}
    if(shouldRender)await renderDirectorVideo();
  };
  const button=document.querySelector('#director-render');if(button)button.onclick=()=>renderDirectorVideo();
}

let editorScene=0,editorTab='scenes',editorTime=0;
const editorUndo=new Map(),editorRedo=new Map();
function editorPlan(){return normalizedDirectorPlan(current?.videoDraft||defaultVideoPlan())}
function editorLatest(){return videoJobs.find(item=>item.id===current?.latestVideoJobId)||videoJobs.find(item=>item.creativeId===current?.id)}
function editorVideoIsCurrent(job=editorLatest()){return !!job&&job.status==='ready'&&job.brand===current?.brand&&job.color===(current?.color||state.brand.color)&&(job.imageVersion||null)===(current?.imageVersion||null)&&!directorAudioChanges.has(current?.id)&&JSON.stringify(normalizedDirectorPlan(job.plan))===JSON.stringify(editorPlan())}
function editorChat(){
  const history=current?.conversation||[];
  return `<section class="director-chat editor-chat"><div class="director-chat-head"><div><b>Ask Bloom</b><small>대화로 광고를 기획하고 수정하세요.</small></div><button class="textbtn" id="director-new" ${generating||directorAttaching?'disabled':''}>새 대화</button></div><div class="director-transcript" id="director-transcript" aria-live="polite">${history.length?history.map(item=>`<div class="director-message ${item.role}"><span>${item.role==='user'?'나':'Bloom'}</span><p>${esc(item.text)}</p></div>`).join(''):`<div class="director-message assistant"><span>Bloom</span><p>${current?'이 광고를 어떻게 바꾸고 싶으세요? 이전 기획과 제작 결과를 참고해 수정할게요.':'어떤 광고를 만들까요? 제품 사진과 함께 원하는 분위기·타깃·메시지를 이야기해주세요.'}</p></div>`}${pendingDirector?`<div class="director-message user"><span>나</span><p>${esc(pendingDirector)}</p></div>`:''}${generating?'<div class="director-thinking" role="status">기획과 작업 결과를 확인하고 있어요…</div>':''}${current?editorChecklist():''}</div><div class="director-attachments">${creativeImage(current)?`<img src="${esc(creativeImage(current))}" alt="첨부한 제품 사진"><span>제품 사진</span>`:''}${current&&videoAudio.has(current.id)?`<span>${esc(videoAudio.get(current.id).name)}</span><button id="director-mute" class="textbtn">오디오 제거</button>`:''}</div><form id="director-form" class="director-composer"><label for="director-message" class="sr-only">광고 제작 요청</label><textarea id="director-message" name="message" maxlength="2000" required rows="3" ${generating||directorAttaching?'disabled':''} placeholder="만들고 싶은 광고를 설명해주세요…">${esc(directorDrafts.get(current?.id||'new')||'')}</textarea><div class="director-composer-actions"><label class="btn filebutton">사진<input id="director-photo" type="file" accept="image/jpeg,image/png,image/webp" ${generating||directorAttaching?'disabled':''}></label><label class="btn filebutton">오디오<input id="director-audio" type="file" accept="audio/*" ${generating||directorAttaching?'disabled':''}></label><button class="btn primary" ${generating||directorAttaching?'disabled':''}>${directorAttaching?'파일 준비 중…':generating?'기획 중…':'보내기'}</button></div></form><div class="director-suggestions">${['10초로 줄여줘','마지막에 구매 유도 넣어줘','이대로 영상 만들어줘'].map(text=>`<button class="chip" data-director-suggestion="${esc(text)}" ${generating?'disabled':''}>${text}</button>`).join('')}</div><p class="director-data-note">대화와 사진을 연결된 AI에 전송합니다. 현재 사진 기반 모션 광고를 지원합니다.</p>${directorError?`<p class="posterror" role="alert">${esc(directorError)}</p>`:''}</section>`;
}
function editorChecklist(){
  const ready=readyForDirector(),job=editorLatest();
  const rows=[['기획·대본',ready?'준비됨':'대화 중'],['3개 장면',ready?'준비됨':'기획 대기'],['제품 사진',creativeImage(current)?'첨부됨':'필요'],['자막',ready?'준비됨':'기획 대기'],['오디오',videoAudio.has(current.id)?'첨부됨':job?.hasAudio?'이전 영상에 포함':'선택 사항'],['영상',editorVideoIsCurrent(job)?'완성됨':job&&['queued','rendering'].includes(job.status)?'제작 중':job?.status==='failed'?'실패':'제작 전']];
  return `<div class="editor-checklist"><b>${esc(current.name)} · ${editorPlan().duration}초</b>${rows.map(([label,status])=>`<div><span>${label}</span><small>${status}</small></div>`).join('')}</div>`;
}
function conversationStudio(){
  const plan=editorPlan(),job=editorLatest(),ready=readyForDirector();
  return `<div class="render-editor"><header class="editor-projectbar"><div><span class="editor-project-type">광고 영상</span><b>${esc(current?.name||'새 광고 프로젝트')}</b></div><div class="editor-project-actions"><button class="btn" id="director-variations" ${!current||generating?'disabled':''}>이 방향으로 여러 시안</button><span>${plan.duration}초 · ${plan.aspect}</span><button id="director-render" class="btn primary" ${!ready||!creativeImage(current)||!videoCapabilities.available||generating||renderingDirector||job&&['queued','rendering'].includes(job.status)?'disabled':''}>${renderingDirector?'제작 요청 중…':editorVideoIsCurrent(job)?'다시 제작':'영상 제작'}</button>${editorVideoIsCurrent(job)?`<a class="btn editor-export" href="${esc(job.fileUrl)}?download=1" download="bloom-ad.mp4">Export MP4</a>`:'<button class="btn editor-export" disabled>Export MP4</button>'}</div></header><div class="editor-body"><nav class="editor-tools" aria-label="영상 편집 도구">${[['scenes','campaign','장면'],['captions','menu','자막'],['settings','brand','스타일']].map(([tab,symbol,label])=>`<button data-editor-tab="${tab}" class="${editorTab===tab?'active':''}" ${generating?'disabled':''}>${icon(symbol)}<span>${label}</span></button>`).join('')}<button id="editor-upload" ${generating||directorAttaching?'disabled':''}>${icon('folder')}<span>업로드</span></button><button id="editor-audio" ${generating?'disabled':''}>${icon('bell')}<span>오디오</span></button></nav><section class="editor-center"><div id="director-preview">${directorPreview()}</div><div class="editor-playback"><div><button class="iconbutton" id="editor-undo" title="기획 변경 되돌리기" ${!editorUndo.get(current?.id)?.length||generating?'disabled':''}>↶</button><button class="iconbutton" id="editor-redo" title="기획 변경 다시 적용" ${!editorRedo.get(current?.id)?.length||generating?'disabled':''}>↷</button></div><div><button class="editor-play" id="editor-play" aria-label="영상 재생 또는 일시 정지" ${!editorVideoIsCurrent(job)?'disabled':''}>▶</button><span id="editor-time">${editorTime.toFixed(1)} / ${plan.duration}.0초</span></div><span>${editorVideoIsCurrent(job)?'완성 영상':'기획 미리보기'}</span></div><div id="editor-timeline">${editorTimeline()}</div><div class="editor-inspector">${editorInspector()}</div></section>${editorChat()}</div></div><details class="director-advanced"><summary>이미지·원고·세부 편집 도구 열기</summary>${legacyStudio()}</details>`;
}
function directorPreview(){
  const plan=editorPlan(),job=editorLatest(),ready=readyForDirector();
  const scene=plan.scenes[editorScene]||plan.scenes[0];
  return `<div class="editor-canvas"><span class="editor-canvas-label">${plan.duration}초 · ${plan.aspect} · ${looks[plan.style]} · ${motions[plan.motion]}</span>${editorVideoIsCurrent(job)?`<video id="editor-player" class="director-player" controls playsinline preload="metadata" poster="${esc(job.posterUrl)}" src="${esc(job.fileUrl)}"></video><a class="editor-canvas-download" href="${esc(job.fileUrl)}?download=1" download="bloom-ad.mp4">MP4 다운로드</a>`:current?.image?`<div class="editor-still ${plan.aspect==='1:1'?'square':''}"><img src="${esc(creativeImage(current))}" alt="제품 사진 기획 미리보기"><div><b>${ready?esc(scene.title):'대화로 광고를 기획해보세요'}</b><p>${ready?esc(scene.body):''}</p><small>${esc(current.brand)}</small></div></div>`:'<div class="editor-canvas-empty"><span>✳</span><b>당신의 다음 광고</b><p>오른쪽에서 제품 사진과 원하는 광고를 이야기해주세요.</p></div>'}${job&&['queued','rendering'].includes(job.status)?`<div class="editor-render-overlay" role="status"><b>${job.status==='queued'?'제작 대기 중':'영상 제작 중'}</b><progress max="100" value="${job.progress||0}"></progress><span>${job.progress||0}%</span></div>`:''}${job?.status==='ready'&&!editorVideoIsCurrent(job)?'<p class="editor-stale">수정한 기획의 미리보기입니다. 영상 제작을 누르면 변경 사항을 MP4에 반영합니다.</p>':''}${job?.status==='failed'?`<p class="editor-stale posterror" role="alert">${esc(job.error)}</p>`:''}</div>`;
}
function editorTimeline(){
  const plan=editorPlan(),ready=readyForDirector();
  return `<div class="editor-timeline-axis">${Array.from({length:7},(_,i)=>`<span>${(i*plan.duration/6).toFixed(i*plan.duration%6?1:0)}s</span>`).join('')}</div><input class="editor-seek" id="editor-seek" type="range" min="0" max="${plan.duration}" step="0.1" value="${Math.min(editorTime,plan.duration)}" aria-label="영상 재생 위치"><div class="editor-track"><span class="editor-track-name">자막</span><div>${plan.scenes.map((scene,i)=>`<button data-editor-scene="${i}" class="editor-caption-clip ${editorScene===i?'selected':''}" ${!ready||generating?'disabled':''}>${ready?esc(scene.title):'장면 '+(i+1)}</button>`).join('')}</div></div><div class="editor-track"><span class="editor-track-name">장면</span><div>${plan.scenes.map((scene,i)=>`<button class="editor-video-clip ${editorScene===i?'selected':''}" data-editor-scene="${i}" ${!ready||generating?'disabled':''}>${creativeImage(current)?`<img src="${esc(creativeImage(current))}" alt="">`:''}<span>장면 ${i+1} · ${(plan.duration/3).toFixed(1)}초</span></button>`).join('')}</div></div><div class="editor-track"><span class="editor-track-name">오디오</span><button class="editor-audio-clip ${current&&videoAudio.has(current.id)?'attached':''}" id="editor-track-audio" ${generating?'disabled':''}>${current&&videoAudio.has(current.id)?esc(videoAudio.get(current.id).name):editorLatest()?.hasAudio?'완성 영상에 오디오 포함 · 변경하려면 첨부':'음성 또는 음악 파일 추가 (선택)'}</button></div>`;
}
function editorInspector(){
  const plan=editorPlan(),scene=plan.scenes[editorScene];
  return `<form id="editor-scene-form"><div class="editor-inspector-head"><b>${editorTab==='settings'?'영상 스타일':'장면 '+(editorScene+1)+' · 자막 편집'}</b><span>대화로도 변경할 수 있습니다.</span></div>${editorTab==='settings'?`<div class="row"><label class="field">길이 (초)<input name="duration" type="number" min="6" max="30" step="1" value="${plan.duration}" required></label><label class="field">비율<select name="aspect">${['9:16','1:1'].map(value=>`<option ${plan.aspect===value?'selected':''}>${value}</option>`).join('')}</select></label><label class="field">분위기<select name="style">${Object.entries(looks).map(([value,label])=>`<option value="${value}" ${plan.style===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">움직임<select name="motion">${Object.entries(motions).map(([value,label])=>`<option value="${value}" ${plan.motion===value?'selected':''}>${label}</option>`).join('')}</select></label></div>`:`<div class="row"><label class="field">화면 제목<textarea name="title" maxlength="42" required>${esc(scene.title)}</textarea></label><label class="field">보조 문구<textarea name="body" maxlength="60">${esc(scene.body)}</textarea></label></div>`}<button class="btn" ${!current||generating?'disabled':''}>${editorTab==='settings'?'스타일 적용':'장면에 적용'}</button></form>`;
}
function rememberEditorPlan(plan){if(!current)return;editorUndo.set(current.id,[...(editorUndo.get(current.id)||[]),structuredClone(plan)].slice(-20));editorRedo.set(current.id,[])}
async function applyEditorPlan(plan,remember=true){if(!current||generating)return;captureDraft();if(remember)rememberEditorPlan(editorPlan());current.videoDraft=plan;editorTime=Math.min(editorTime,plan.duration);current.directorReady=true;await saveCreative();render()}
function updateEditorChrome(){
  const job=editorLatest(),ready=editorVideoIsCurrent(job),button=document.querySelector('#director-render');
  if(button){button.disabled=!readyForDirector()||!creativeImage(current)||!videoCapabilities.available||generating||renderingDirector||!!job&&['queued','rendering'].includes(job.status);button.textContent=renderingDirector?'제작 요청 중…':ready?'다시 제작':'영상 제작'}
  const exported=document.querySelector('.editor-export');if(exported)exported.outerHTML=ready?`<a class="btn editor-export" href="${esc(job.fileUrl)}?download=1" download="bloom-ad.mp4">Export MP4</a>`:'<button class="btn editor-export" disabled>Export MP4</button>';
  const play=document.querySelector('#editor-play');if(play)play.disabled=!ready;
  const checklist=document.querySelector('.editor-checklist');if(checklist)checklist.outerHTML=editorChecklist();
}
function bindEditorPlayback(){
  const player=document.querySelector('#editor-player'),play=document.querySelector('#editor-play'),seek=document.querySelector('#editor-seek');
  const display=time=>{editorTime=time;const label=document.querySelector('#editor-time');if(label)label.textContent=time.toFixed(1)+' / '+editorPlan().duration+'.0초';if(seek)seek.value=String(time)};
  if(player){player.ontimeupdate=()=>display(player.currentTime);player.onplay=()=>{play.textContent='Ⅱ'};player.onpause=()=>{play.textContent='▶'};player.onended=()=>{play.textContent='▶'}}
  if(play)play.onclick=async()=>{if(!player)return;try{if(player.paused)await player.play();else player.pause()}catch(error){toast('영상을 재생하지 못했습니다. MP4로 저장해 확인해주세요.')}};
  if(seek)seek.oninput=()=>{const value=Number(seek.value);display(value);if(player)player.currentTime=value;else{const next=Math.min(2,Math.floor(value/(editorPlan().duration/3)));if(next!==editorScene){editorScene=next;const inspector=document.querySelector('.editor-inspector');if(inspector)inspector.innerHTML=editorInspector();document.querySelectorAll('[data-editor-scene]').forEach(button=>button.classList.toggle('selected',Number(button.dataset.editorScene)===next));bindEditor()}updateDirectorPreview()}};
}
function bindEditor(){
  document.querySelectorAll('[data-editor-tab]').forEach(button=>button.onclick=()=>{if(generating)return;captureDraft();editorTab=button.dataset.editorTab;render()});
  document.querySelectorAll('[data-editor-scene]').forEach(button=>button.onclick=()=>{if(generating)return;captureDraft();editorScene=Number(button.dataset.editorScene);editorTab='captions';editorTime=editorScene*editorPlan().duration/3;render();const player=document.querySelector('#editor-player');if(player)player.currentTime=editorTime});
  const upload=document.querySelector('#editor-upload');if(upload)upload.onclick=()=>document.querySelector('#director-photo').click();
  for(const id of ['editor-audio','editor-track-audio']){const button=document.getElementById(id);if(button)button.onclick=()=>document.querySelector('#director-audio').click()}
  const form=document.querySelector('#editor-scene-form');if(form)form.onsubmit=async event=>{event.preventDefault();const data=new FormData(form),plan=structuredClone(editorPlan());if(editorTab==='settings'){const duration=Number(data.get('duration'));if(!Number.isInteger(duration)||duration<6||duration>30){toast('영상 길이는 6~30초로 설정해주세요.');return}Object.assign(plan,{duration,aspect:data.get('aspect'),style:data.get('style'),motion:data.get('motion')})}else{const title=data.get('title').trim();if(!title){toast('장면 제목을 입력해주세요.');return}plan.scenes[editorScene]={title,body:data.get('body').trim()}}await applyEditorPlan(plan)};
  for(const [id,from,to] of [['editor-undo',editorUndo,editorRedo],['editor-redo',editorRedo,editorUndo]]){const button=document.getElementById(id);if(button)button.onclick=async()=>{const stack=from.get(current?.id);if(!stack?.length||generating)return;to.set(current.id,[...(to.get(current.id)||[]),structuredClone(editorPlan())]);await applyEditorPlan(stack.pop(),false)}}
  bindEditorPlayback();
}

let studioMode='chat',batchDraft={},batchDraftImage='',activeBatchId='',batchError='',batchTimer;
function studio(){return `<div class="creation-modes" role="tablist" aria-label="영상 제작 방식"><button role="tab" aria-selected="${studioMode==='chat'}" data-create-mode="chat" ${generating||directorAttaching?'disabled':''}><b>대화하며 만들기</b><span>함께 기획하고 원하는 부분을 수정하세요.</span></button><button role="tab" aria-selected="${studioMode==='batch'}" data-create-mode="batch" ${generating||directorAttaching?'disabled':''}><b>여러 시안 만들기</b><span>길이·수량을 정하고 서로 다른 광고를 비교하세요.</span></button></div>${studioMode==='batch'?batchStudio():conversationStudio()}`}
function batchGroups(){const groups=new Map();for(const item of state.creatives)if(item.batchId){if(!groups.has(item.batchId))groups.set(item.batchId,[]);groups.get(item.batchId).push(item)}return[...groups.entries()].map(([id,items])=>({id,items:items.sort((a,b)=>a.batchIndex-b.batchIndex)}))}
function currentBatch(){const groups=batchGroups();return groups.find(group=>group.id===activeBatchId)||groups.find(group=>group.id===current?.batchId)||groups[0]||null}
function batchValues(){return{product:batchDraft.product??current?.directorBrief?.product??'',audience:batchDraft.audience??current?.directorBrief?.audience??'',goal:batchDraft.goal??current?.directorBrief?.goal??'제품 소개',duration:batchDraft.duration??current?.videoDraft?.duration??15,count:batchDraft.count??5,aspect:batchDraft.aspect??current?.videoDraft?.aspect??'9:16',useReference:batchDraft.useReference??readyForDirector()}}
function batchStudio(){
  const values=batchValues(),image=batchDraftImage||creativeImage(current),group=currentBatch();
  return `<div class="heading"><div><div class="eyebrow">CREATE & COMPARE</div><h1>여러 광고 시안을 한 번에</h1><p class="sub">같은 제품을 다른 도입·메시지·구성으로 제작하고 비교하세요.</p></div></div><div class="batch-workbench"><section class="card panel"><h2>이번에 만들 광고</h2><form id="batch-form"><label class="field">제품 설명<textarea name="product" maxlength="500" required ${generating?'readonly':''} placeholder="예: 바쁜 아침에 즐기는 오트 라떼">${esc(values.product)}</textarea></label><div class="batch-photo">${image?`<img src="${esc(image)}" alt="일괄 제작에 사용할 제품 사진">`:'<p>제품 사진을 첨부해주세요.</p>'}<label class="btn filebutton">${image?'사진 변경':'제품 사진 첨부'}<input id="batch-photo" type="file" accept="image/jpeg,image/png,image/webp" ${generating||directorAttaching?'disabled':''}></label></div><div class="row"><label class="field">영상 길이 (초)<input name="duration" type="number" min="6" max="30" step="1" required value="${esc(values.duration)}" ${generating?'readonly':''}></label><label class="field">시안 수량<input name="count" type="number" min="1" max="5" step="1" required value="${esc(values.count)}" ${generating?'readonly':''}></label></div><label class="field">화면 비율<select name="aspect" ${generating?'disabled':''}><option value="9:16" ${values.aspect==='9:16'?'selected':''}>세로형 9:16</option><option value="1:1" ${values.aspect==='1:1'?'selected':''}>정사각형 1:1</option></select></label><label class="field">광고 목적<input name="goal" maxlength="300" value="${esc(values.goal)}" ${generating?'readonly':''}></label><label class="field">타깃 (선택)<input name="audience" maxlength="300" value="${esc(values.audience)}" placeholder="예: 20대 직장인" ${generating?'readonly':''}></label>${current&&readyForDirector()?`<label class="batch-reference"><input type="checkbox" name="useReference" ${values.useReference?'checked':''} ${generating?'disabled':''}> 현재 광고 기획을 기준으로 변형 만들기</label>`:''}<button class="btn primary wide" ${generating||directorAttaching||!videoCapabilities.available?'disabled':''}>${generating?'서로 다른 시안을 기획하고 있어요…':`${esc(values.count)}개 영상 만들기`}</button><p class="sub">AI가 서로 다른 광고 가설을 기획한 뒤 같은 영상 엔진에서 순서대로 렌더링합니다. 일괄 시안은 무음으로 제작하며 선택 후 오디오를 추가할 수 있습니다. 제품 사진과 설명을 AI에 전송하며 현재 사진 기반 모션 광고를 지원합니다.</p><p id="batch-error" class="posterror" role="alert">${esc(batchError)}</p></form></section><section class="batch-gallery"><div class="sectionhead"><h2>시안 비교</h2>${batchGroups().length?`<select id="batch-history" aria-label="시안 묶음 선택">${batchGroups().map((entry,index)=>`<option value="${esc(entry.id)}" ${entry.id===group?.id?'selected':''}>${esc(entry.items[0].brand)} · ${entry.items.length}개 시안${index===0?' (최근)':''}</option>`).join('')}</select>`:''}</div><div id="batch-results">${batchResults()}</div></section></div>`;
}
function batchJob(item){return videoJobs.find(job=>job.id===item.latestVideoJobId)||videoJobs.find(job=>job.creativeId===item.id)}
function batchJobCurrent(item,job){return !!job&&job.status==='ready'&&job.brand===item.brand&&job.color===(item.color||state.brand.color)&&(job.imageVersion||null)===(item.imageVersion||null)&&!directorAudioChanges.has(item.id)&&JSON.stringify(normalizedDirectorPlan(job.plan))===JSON.stringify(normalizedDirectorPlan(item.videoDraft))}
function batchResults(){
  const group=currentBatch();if(!group)return `<div class="card batch-empty"><span>✳</span><h2>서로 다른 광고를 비교해보세요</h2><p class="sub">예: 같은 15초 영상도 문제 제기, 일상의 순간, 제품 소개 등 다른 관점으로 만듭니다. 완성된 시안을 선택해 대화로 다듬을 수 있습니다.</p></div>`;
  let complete=0,pending=0,failed=0,unstarted=0;
  for(const item of group.items){const job=batchJob(item);if(batchJobCurrent(item,job))complete++;else if(job&&['queued','rendering'].includes(job.status))pending++;else if(job?.status==='failed')failed++;else if(!job)unstarted++}
  return `<div class="batch-summary" role="status"><span>전체 ${group.items.length}개 · 완료 ${complete} · 제작 중 ${pending}${failed?' · 실패 '+failed:''}${unstarted?' · 기획 완료 '+unstarted:''}</span>${failed||unstarted?`<button class="btn" id="batch-retry" ${generating?'disabled':''}>미제작·실패 시안 제작</button>`:''}</div><div class="batch-cards">${group.items.map(item=>{
    const job=batchJob(item),fresh=batchJobCurrent(item,job),active=job&&['queued','rendering'].includes(job.status);
    return `<article class="card batch-card"><div class="batch-card-head"><span>시안 ${item.batchIndex+1}</span><span class="tag">${fresh?'완성':active?job.status==='queued'?'대기 중':'제작 중':job?.status==='failed'?'실패':job?'수정 기획':'기획 완료'}</span></div><h3>${esc(item.batchAngle)}</h3><p class="batch-hypothesis">${esc(item.batchHypothesis)}</p>${job?.status==='ready'?`${!fresh?'<p class="notice">아래는 이전 영상입니다. 대화형 편집기에서 수정 기획으로 재제작하세요.</p>':''}<video controls playsinline preload="metadata" poster="${esc(job.posterUrl)}" src="${esc(job.fileUrl)}"></video>`:`<div class="batch-card-image"><img src="${esc(creativeImage(item))}" alt="시안 ${item.batchIndex+1} 제품 사진"><span>${esc(item.videoDraft.scenes[0].title)}</span></div>${active?`<progress max="100" value="${job.progress||0}"></progress>`:''}`}${job?.status==='failed'?`<p class="posterror">${esc(job.error)}</p>`:''}<p class="sub">${item.videoDraft.duration}초 · ${item.videoDraft.aspect} · ${looks[item.videoDraft.style]}</p><div class="row"><button class="btn primary" data-batch-open="${esc(item.id)}" ${generating?'disabled':''}>이 시안으로 대화하기</button>${job?.status==='ready'?`<a class="btn" href="${esc(job.fileUrl)}?download=1" download="bloom-variant-${item.batchIndex+1}.mp4">${fresh?'MP4 저장':'이전 영상 저장'}</a>`:''}</div></article>`;
  }).join('')}</div>`;
}
function captureBatchDraft(){const form=document.querySelector('#batch-form');if(!form||generating)return;const data=new FormData(form);batchDraft={...batchDraft,...Object.fromEntries(data),useReference:data.get('useReference')==='on'}}
function openBatchVariant(id){if(generating||directorAttaching)return;captureBatchDraft();const item=state.creatives.find(entry=>entry.id===id);if(!item)return;current=structuredClone(item);draft=null;messages=[];editorScene=0;editorTime=0;editorTab='scenes';directorError='';studioMode='chat';render()}
async function queueBatchVariants(ids){
  const result=await api('/api/videos/batch',{creativeIds:ids});
  for(const job of result.jobs){const item=state.creatives.find(entry=>entry.id===job.creativeId);if(item){item.latestVideoJobId=job.id;recordDirectorExecution(item,job)}}
  if(current){const latest=state.creatives.find(item=>item.id===current.id);if(latest)current=structuredClone(latest)}
  await persist();await saved();await refreshVideos();return result;
}
function pollBatch(){
  clearTimeout(batchTimer);const ids=new Set(currentBatch()?.items.map(item=>item.id)||[]);
  if(view!=='studio'||studioMode!=='batch'||!videoJobs.some(job=>ids.has(job.creativeId)&&['queued','rendering'].includes(job.status)))return;
  batchTimer=setTimeout(async()=>{try{await refreshVideos();const target=document.querySelector('#batch-results');if(target&&studioMode==='batch'){target.innerHTML=batchResults();bindBatchResults();pollBatch()}}catch(error){batchError=error.message;const target=document.querySelector('#batch-error');if(target)target.textContent=batchError}},1500);
}
function bindBatchResults(){
  document.querySelectorAll('[data-batch-open]').forEach(button=>button.onclick=()=>openBatchVariant(button.dataset.batchOpen));
  const retry=document.querySelector('#batch-retry');if(retry)retry.onclick=async()=>{const ids=currentBatch().items.filter(item=>!batchJob(item)||batchJob(item).status==='failed').map(item=>item.id);if(!ids.length)return;retry.disabled=true;try{await queueBatchVariants(ids);batchError='';render()}catch(error){batchError=error.message;render()}};
}
function bindCreationModes(){
  document.querySelectorAll('[data-create-mode]').forEach(button=>button.onclick=()=>{if(generating||directorAttaching)return;captureDraft();captureBatchDraft();studioMode=button.dataset.createMode;batchError='';render();if(studioMode==='batch')refreshVideos().then(()=>{if(studioMode==='batch'&&view==='studio'){document.querySelector('#batch-results').innerHTML=batchResults();bindBatchResults();pollBatch()}}).catch(error=>toast(error.message))});
  const variants=document.querySelector('#director-variations');if(variants)variants.onclick=()=>{if(generating||directorAttaching)return;captureDraft();batchDraft={};batchDraftImage='';studioMode='batch';render()};
  const form=document.querySelector('#batch-form');if(!form)return;
  form.oninput=()=>{captureBatchDraft();const button=form.querySelector('.primary');if(button)button.textContent=String(batchDraft.count||5)+'개 영상 만들기'};
  form.querySelector('#batch-photo').onchange=async event=>{const file=event.target.files[0];if(!file)return;captureBatchDraft();directorAttaching=true;render();try{batchDraftImage=await readProductPhoto(file);batchError=''}catch(error){batchError=error.message}finally{directorAttaching=false;render()}};
  const history=document.querySelector('#batch-history');if(history)history.onchange=()=>{captureBatchDraft();activeBatchId=history.value;render()};
  form.onsubmit=async event=>{
    event.preventDefault();if(generating||directorAttaching)return;captureBatchDraft();const values=batchValues(),image=batchDraftImage||creativeImage(current);
    if(!image){batchError='제품 사진을 첨부해주세요.';render();return}
    if(!connection.configured){settingsModal();return}
    const input={product:values.product.trim(),goal:values.goal,audience:values.audience,count:Number(values.count),duration:Number(values.duration),aspect:values.aspect};
    if(!input.product||!Number.isInteger(input.count)||input.count<1||input.count>5||!Number.isInteger(input.duration)||input.duration<6||input.duration>30){batchError='제품 설명, 길이(6~30초), 수량(1~5개)을 확인해주세요.';render();return}
    const reference=values.useReference&&current?structuredClone(current):null;let savedPlans=false;
    generating=true;batchError='';render();
    try{
      state.assets??=[];let asset=state.assets.find(item=>item.data===image);if(!asset){asset={id:crypto.randomUUID(),data:image};state.assets.push(asset)}
      await persist();await saved();
      const response=await api('/api/batch-plan',{...input,assetId:asset.id,...(reference?{creativeId:reference.id}:{})});
      const id=crypto.randomUUID(),brand=reference?.brand||state.brand.name;
      const records=response.variants.map((item,index)=>({id:crypto.randomUUID(),brand,name:item.name,prompt:input.product,headline:item.headline,caption:item.caption,script:item.script,channel:reference?.channel||'Instagram',format:'15초 광고 영상',variant:0,color:reference?.color||state.brand.color,image:'',imageRef:asset.id,imageVersion:asset.id,videoDraft:item.plan,directorReady:true,directorBrief:{product:input.product,audience:input.audience,tone:looks[item.plan.style],goal:input.goal},batchId:id,batchIndex:index,batchAngle:item.angle,batchHypothesis:item.hypothesis,conversation:[...(reference?.conversation||[]).slice(-20),{role:'user',text:`${input.product}\n${input.duration}초 ${input.count}개 시안 · 목적: ${input.goal}${input.audience?' · 타깃: '+input.audience:''}`},{role:'assistant',text:item.angle+'\n'+item.hypothesis}],executions:[{tool:'update_plan',status:'completed',at:new Date().toISOString()}]}));
      state.creatives.unshift(...records);current=structuredClone(records[0]);activeBatchId=id;draft=null;await persist();await saved();savedPlans=true;
      await queueBatchVariants(records.map(item=>item.id));
    }catch(error){batchError=(savedPlans?'시안 기획은 저장했습니다. 제작 상태를 확인하고 필요한 시안을 다시 요청해주세요. ':'')+error.message}
    finally{generating=false;render();pollBatch()}
  };
  bindBatchResults();pollBatch();
}

const performanceForms={};
function capturePerformanceForms(){for(const form of document.querySelectorAll('#experiment-form,#observation-form,#performance-decision,#performance-import'))performanceForms[form.id]={values:Object.fromEntries(new FormData(form)),checked:[...form.querySelectorAll('[type=checkbox]')].filter(el=>el.checked).map(el=>el.value)}}
let performanceData={experiments:[],observationCount:0},performanceActive='',performanceBusy=false,performanceError='';
const perfMoney=value=>value===null||value===undefined?'—':'₩'+Math.round(value).toLocaleString('ko-KR');
const perfPercent=value=>value===null||value===undefined?'—':(value*100).toFixed(2)+'%';
const perfActions={hold:'추가 관측',iterate:'다음 가설 제작',review_pause:'중단 검토',review_scale:'확대 실험 검토'};
async function loadPerformance(){try{await saved();performanceData=await api('/api/performance');performanceError=''}catch(error){performanceError=error.message}if(view==='performance')render()}
async function changePerformance(action,input){if(performanceBusy)return;capturePerformanceForms();performanceBusy=true;const button=document.querySelector('#performance-panel');button?.setAttribute('aria-busy','true');try{await saved();const response=await api('/api/performance/'+action,{...input,revision});state=response.state;revision=response.revision;performanceData=response.report;performanceError='';delete performanceForms[({experiments:'experiment-form',observations:input.csv!==undefined?'performance-import':'observation-form',decisions:'performance-decision'})[action]];performanceActive=action==='experiments'?performanceData.experiments[0].id:input.experimentId;toast('성과 실험 기록을 저장했습니다.')}catch(error){performanceError=error.message}finally{performanceBusy=false;if(view==='performance')render()}}
function performanceView(){
  const selected=performanceData.experiments.find(e=>e.id===performanceActive)||performanceData.experiments[0];
  const today=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'});
  return `<div class="heading"><div><div class="eyebrow">BLOOM · AI CMO</div><h1>성과 실험과 다음 결정</h1><p class="sub">사업 목표와 광고 가설을 정하고, 실제 결과를 다음 제작에 반영하세요.</p></div><button class="btn" id="performance-refresh">성과 새로고침</button></div><div class="notice">현재는 직접 입력·CSV로 실제 성과를 등록합니다. 광고 매체·쇼핑몰 자동 동기화와 유료 광고 자동 집행은 연결되지 않았습니다. 관측 성과는 광고의 증분 효과나 통계적 승자를 의미하지 않습니다. 연결된 AI로 다음 광고를 기획할 때 관련 성과와 의사결정 요약을 함께 전송합니다.</div><p class="posterror" role="alert">${esc(performanceError)}</p><div class="performance-layout" id="performance-panel"><section class="card panel"><h2>새 실험 계획</h2><form id="experiment-form"><label class="field">실험 이름<input name="name" required maxlength="100" placeholder="예: 오트 라떼 첫 구매 소구점 비교"></label><label class="field">상품 식별명<input name="product" required maxlength="500" placeholder="예: oat-latte-250ml"></label><label class="field">타깃 조건<input name="audience" required maxlength="500" placeholder="예: 국내 신규 고객 / 관심사 타깃"></label><div class="row"><label class="field">채널<select name="channel"><option>Instagram</option><option>Facebook</option><option>YouTube</option></select></label><label class="field">목표 CPA (원)<input name="targetCpa" type="number" min="1" max="1000000000" required></label></div><label class="field">랜딩페이지<input name="landingUrl" type="url" required maxlength="2000" placeholder="https://shop.example.com/product"></label><label class="field">전환 기여 기준<input name="attribution" required maxlength="200" placeholder="예: 클릭 후 7일 구매 / 중복 제거한 주문"></label><div class="row"><label class="field">실험 총예산 (원)<input name="maxSpend" type="number" min="1" max="1000000000" required></label><label class="field">광고비 전 공헌이익률 (%)<input name="marginPercent" type="number" min="0.01" max="100" step="0.01" required placeholder="원가·변동비 반영"></label></div><div class="row"><label class="field">시작일<input name="startDate" type="date" required value="${today}"></label><label class="field">종료일<input name="endDate" type="date" required value="${today}"></label></div><label class="field">시험 가설<textarea name="hypothesis" required maxlength="1000" placeholder="어떤 메시지가 어떤 고객 반응을 개선할 것으로 보나요?"></textarea></label><fieldset class="experiment-creatives"><legend>같은 브랜드·채널의 광고 1~5개 선택</legend>${state.creatives.map(c=>`<label><input type="checkbox" name="creativeIds" value="${esc(c.id)}">${esc(c.name)} <small>${esc(c.brand)} · ${esc(c.channel)}</small></label>`).join('')||'<p class="sub">먼저 스튜디오에서 광고를 만들어주세요.</p>'}</fieldset><button class="btn primary wide" ${performanceBusy||!state.creatives.length?'disabled':''}>실험 계획 저장</button><p class="sub">문구·장면 기획·사진 버전은 등록 시점에 고정됩니다. 나중에 광고를 수정해도 과거 성과의 소재 기록은 바뀌지 않습니다. 같은 광고의 실험 기간은 겹칠 수 없습니다. 금액은 모두 KRW입니다.</p></form></section><section class="performance-detail">${performanceData.experiments.length?`<label class="field">실험 선택<select id="performance-history">${performanceData.experiments.map(e=>`<option value="${esc(e.id)}" ${e.id===selected?.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label>${performanceDetail(selected)}`:'<div class="card empty"><h2>첫 실험을 등록하세요</h2><p class="sub">제작한 광고를 실제 매체에서 집행한 뒤 성과를 등록하세요.<br>데이터가 없으면 성과와 예측값을 표시하지 않습니다.</p></div>'}</section></div>`;
}
function performanceDetail(e){
  const m=e.metrics,forecast=e.forecast;
  return `<div class="card panel"><div class="sectionhead"><h2>${esc(e.name)}</h2><span class="tag">관측 ${e.rows}행</span></div><p class="sub">${esc(e.product)} · ${esc(e.audience)} · ${esc(e.channel)}<br>${esc(e.startDate)} ~ ${esc(e.endDate)} · ${esc(e.attribution)}<br>랜딩: ${esc(e.landingUrl)}</p><div class="performance-metrics">${[['광고비',e.rows?perfMoney(m.spend):'—'],['환불 반영 매출',e.rows?perfMoney(m.netRevenue):'—'],['CPA',perfMoney(m.cpa)],['ROAS',m.roas===null?'—':m.roas.toFixed(2)],['광고비 차감 기여이익 추정',e.rows?perfMoney(m.contribution):'—'],['실험 예산 잔액',perfMoney(m.budgetRemaining)]].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><p class="sub">기여이익 추정 = (매출 − 환불) × ${(e.marginRate*100).toFixed(1)}% − 광고비. 고정비는 포함하지 않습니다.</p><div class="performance-table"><table><thead><tr><th>소재 / 가설</th><th>클릭 / 구매</th><th>CTR / CVR</th><th>CPA / ROAS</th><th>다음 제작</th></tr></thead><tbody>${e.arms.map(a=>`<tr><td><b>${esc(a.snapshot.name)}</b><p>${esc(a.snapshot.batchAngle||a.snapshot.headline)}</p><small>${esc(a.hypothesis)}</small></td><td>${a.metrics.clicks} / ${a.metrics.purchases}</td><td>${perfPercent(a.metrics.ctr)} / ${perfPercent(a.metrics.cvr)}</td><td>${perfMoney(a.metrics.cpa)} / ${a.metrics.roas===null?'—':a.metrics.roas.toFixed(2)}</td><td><button class="btn" data-performance-creative="${esc(a.creativeId)}">대화로 개선</button></td></tr>`).join('')}</tbody></table></div></div><div class="card panel"><h2>다음 행동 검토</h2><p><b>${esc(perfActions[e.suggestion.action])}</b> · ${esc(e.suggestion.reason)}</p><form id="performance-decision"><label class="field">다음 행동<select name="action">${Object.entries(perfActions).map(([value,label])=>`<option value="${value}" ${value===e.suggestion.action?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">판단 근거·다음 실험<textarea name="note" maxlength="2000" required placeholder="성과 집계 지연, 소재 외 조건과 다음에 바꿀 항목을 기록하세요."></textarea></label><button class="btn primary" ${performanceBusy?'disabled':''}>의사결정 기록</button><p class="sub">권고와 사용자 판단을 기록합니다. 실제 광고 중단·예산 변경은 매체에서 진행하세요.</p></form>${e.decisions.slice(-5).reverse().map(d=>`<div class="decision-entry"><b>${esc(perfActions[d.action])}</b> <small>${esc(d.at.slice(0,10))} · 판단 시점 지출 ${perfMoney(d.evidence.metrics.spend)}</small><p>${esc(d.note)}</p></div>`).join('')}</div><div class="card panel"><h2>사전 성과 추정과 검증</h2>${forecast?`<p class="sub">사전 저장: ${esc(forecast.asOf)} · 과거 실험 ${forecast.baseline.experiments}개 / 클릭 ${forecast.baseline.clicks}회 / 구매 ${forecast.baseline.purchases}건</p><p>과거 기준 CVR <b>${perfPercent(forecast.baseline.cvr)}</b> · 기준 CPA <b>${perfMoney(forecast.scenario.expectedCpa)}</b> · 기준 ROAS <b>${forecast.scenario.expectedRoas.toFixed(2)}</b></p><p>총예산 ${perfMoney(forecast.scenario.budget)} 사용 가정 시 구매 시나리오 ${forecast.scenario.purchasesRange.map(v=>v.toFixed(1)).join(' ~ ')}건<br>기여이익 시나리오 ${forecast.scenario.contributionRange.map(perfMoney).join(' ~ ')}</p><p class="sub">${esc(forecast.assumptions)}</p>${e.validation?`<div class="notice">실제 CVR ${perfPercent(e.validation.observedCvr)} · 기준선과 차이 ${(e.validation.absoluteError*100).toFixed(2)}%p · 과거 통계 범위 ${e.validation.withinHistoricalInterval?'내':'밖'}<p>${esc(e.validation.note)}</p></div>`:'<p class="sub">성과를 등록하면 사전 기준선과 실제 전환율을 비교합니다.</p>'}`:`<p class="sub">${esc(e.forecastCandidate?.reason||'성과 데이터를 확인하고 있습니다.')}</p>${e.forecastCandidate?.available?`<p>동일 조건 과거 ${e.forecastCandidate.baseline.experiments}개 실험을 기준으로 추정할 수 있습니다.</p><button class="btn" id="performance-forecast" ${performanceBusy?'disabled':''}>성과 등록 전 기준선 저장</button>`:''}`}<p class="sub">동일 조건의 과거 기준선이며 광고별 우열을 예측하는 학습 모델은 아닙니다.</p></div><div class="card panel"><h2>실제 성과 등록</h2><p class="sub">클릭 후 구매만 입력하세요. 같은 광고·날짜는 갱신되며 합산하지 않습니다. CSV는 이 실험의 광고 ID와 일별 수치만 받습니다.</p><form id="observation-form"><label class="field">광고<select name="creativeId">${e.arms.map(a=>`<option value="${esc(a.creativeId)}">${esc(a.snapshot.name)}</option>`).join('')}</select></label><div class="row"><label class="field">성과 날짜<input name="date" type="date" required min="${e.startDate}" max="${e.endDate}"></label><label class="field">출처<input name="source" required maxlength="200" placeholder="예: Meta 보고서 / 7일 클릭"></label></div><div class="performance-inputs">${[['spend','광고비'],['impressions','노출'],['clicks','링크 클릭'],['purchases','클릭 후 구매'],['revenue','구매 매출'],['refunds','환불액']].map(([key,label])=>`<label class="field">${label}<input type="number" name="${key}" min="0" step="${['spend','revenue','refunds'].includes(key)?'0.01':'1'}" required></label>`).join('')}</div><button class="btn primary" ${performanceBusy?'disabled':''}>일별 성과 저장</button></form><details class="performance-csv"><summary>CSV로 여러 행 가져오기</summary><button class="btn" id="performance-template">이 실험 CSV 양식 저장</button><form id="performance-import"><label class="field">CSV 파일<input id="performance-file" type="file" accept=".csv,text/csv"></label><label class="field">CSV 내용<textarea name="csv" required maxlength="2000000" placeholder="creativeId,date,spend,impressions,clicks,purchases,revenue,refunds"></textarea></label><label class="field">데이터 출처<input name="source" required maxlength="200"></label><button class="btn" ${performanceBusy?'disabled':''}>검증 후 일괄 저장</button></form></details><h3>최근 등록 출처</h3>${(state.performance?.imports||[]).filter(i=>i.experimentId===e.id).slice(-5).reverse().map(i=>`<p class="sub">${esc(i.at.slice(0,10))} · ${esc(i.source)} · ${i.rows}행 (${i.updated}행 갱신)</p>`).join('')||'<p class="sub">등록된 성과가 없습니다.</p>'}</div>`;
}
function bindPerformance(){
  for(const [id,draft] of Object.entries(performanceForms)){const form=document.getElementById(id);if(!form)continue;for(const el of form.querySelectorAll('input,textarea,select')){if(el.type==='file')continue;if(el.type==='checkbox'){el.checked=draft.checked.includes(el.value)}else if(draft.values[el.name]!==undefined){if(el.localName==='select'){for(const option of el.querySelectorAll('option')){option.selected=(option.getAttribute('value')??option.textContent)===draft.values[el.name];if(option.selected)option.setAttribute('selected','');else option.removeAttribute('selected')}}else el.value=draft.values[el.name]}}}
  document.querySelector('#performance-refresh')?.addEventListener('click',loadPerformance);
  document.querySelector('#performance-history')?.addEventListener('change',event=>{performanceActive=event.target.value;for(const key of ['observation-form','performance-decision','performance-import'])delete performanceForms[key];render()});
  const selected=performanceData.experiments.find(e=>e.id===performanceActive)||performanceData.experiments[0];
  const form=document.querySelector('#experiment-form');if(form)form.onsubmit=async event=>{event.preventDefault();const input=Object.fromEntries(new FormData(form));input.creativeIds=[...form.querySelectorAll('[name=creativeIds]')].filter(el=>el.checked).map(el=>el.value);input.marginRate=Number(input.marginPercent)/100;input.targetCpa=Number(input.targetCpa);input.maxSpend=Number(input.maxSpend);await changePerformance('experiments',input)};
  const observation=document.querySelector('#observation-form');if(observation)observation.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(observation));await changePerformance('observations',{experimentId:selected.id,source:values.source,rows:[Object.fromEntries(Object.entries(values).filter(([k])=>k!=='source').map(([k,v])=>[k,['creativeId','date'].includes(k)?v:Number(v)]))]})};
  const decision=document.querySelector('#performance-decision');if(decision)decision.onsubmit=async event=>{event.preventDefault();await changePerformance('decisions',{...Object.fromEntries(new FormData(decision)),experimentId:selected.id})};
  document.querySelector('#performance-forecast')?.addEventListener('click',()=>changePerformance('forecasts',{experimentId:selected.id}));
  document.querySelector('#performance-template')?.addEventListener('click',()=>download('bloom-performance.csv','\uFEFFcreativeId,date,spend,impressions,clicks,purchases,revenue,refunds\n'+selected.arms.map(a=>a.creativeId+',,,,,,,').join('\n'),'text/csv;charset=utf-8'));
  document.querySelector('#performance-file')?.addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('CSV 파일은 2MB 이하로 선택해주세요.');document.querySelector('#performance-import [name=csv]').value=await file.text()}catch(error){toast(error.message)}});
  const importer=document.querySelector('#performance-import');if(importer)importer.onsubmit=async event=>{event.preventDefault();await changePerformance('observations',{...Object.fromEntries(new FormData(importer)),experimentId:selected.id})};
  document.querySelectorAll('[data-performance-creative]').forEach(button=>button.onclick=()=>{current=structuredClone(state.creatives.find(c=>c.id===button.dataset.performanceCreative));studioMode='chat';draft=null;editorTime=0;editorScene=0;editorTab='scenes';go('studio');toast('등록된 성과와 판단 기록을 다음 대화 기획에 반영합니다.')});
}

async function start(){
  document.querySelector('#app').innerHTML='<p class="startup">작업 공간을 불러오는 중…</p>';
  try{
    const outcome=new URLSearchParams(location.search||'').get('instagram');
    if(instagramNotices[outcome]){instagramNotice=instagramNotices[outcome];view='instagram';window.history?.replaceState(null,'',location.pathname+'#instagram')}
    const [workspace,status]=await Promise.all([api('/api/state'),api('/api/status')]);revision=workspace.revision;connection=status;await Promise.all([refreshInstagram(),refreshVideos()]);
    if(workspace.state)state=workspace.state;
    else{
      let legacy;try{legacy=JSON.parse(localStorage.getItem('bloom.v1'))}catch{}
      if(legacy?.brand&&Array.isArray(legacy.creatives)&&Array.isArray(legacy.campaigns)){
        state=legacy;state.campaigns=state.campaigns.filter(c=>!c.sample&&c.id!=='autopilot-proposal'&&state.creatives.some(item=>item.id===c.creativeId));
        state.creatives=state.creatives.map(c=>({...c,color:state.brand.color}));state.autopilot=false;
      }
      await persist();await saved();
    }
    if(outcome){try{const pending=JSON.parse(sessionStorage.getItem('bloom.oauth-return'));if(pending){current=structuredClone(state.creatives.find(item=>item.id===pending.creativeId)||null);variant=current?.variant||0;draft=pending.draft;sessionStorage.removeItem('bloom.oauth-return')}}catch{}}
    if(view==='performance')performanceData=await api('/api/performance');
    render();
  }catch(error){document.querySelector('#app').innerHTML=`<div class="startup"><h1>작업 공간에 연결하지 못했습니다.</h1><p>${esc(error.message)}</p><p>터미널에서 npm start를 실행한 뒤 <a href="http://localhost:4174">Bloom 열기</a></p><button class="btn" onclick="location.reload()">다시 시도</button></div>`}
}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(generating||directorAttaching||performanceBusy){location.hash=view;return}if(names[next]&&next!==view){captureDraft();view=next;render();if(next==='performance')loadPerformance()}});start();
